[58268] = {id=58268,name="Take the High Ground",level=10,requiredLevel=10,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The commander of the constructs, General Alver, is a master tactician. A frontal assault has no chance of victory against him. It will be a bloodbath. His forces have flanked us and secured the high ground. From that position, he can rain destruction upon us unopposed. We will take the ridge from him before that can happen.",objectivesText="Destroy the three enemy positions.",starts={{npcID=169359,x=0.394,y=0.556,zoneID=11462}},ends={{npcID=169226,x=0.394,y=0.466,zoneID=11462}},coords={x=0.394,y=0.556,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Take the High Ground"},
[58432] = {id=58432,name="Something Old, Something Used",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Want new luckydos? Chordy is best at finding luckydos! Want to go look around with Chordy ? Chordy looks at you pleadingly with his large eye.>",objectivesText="Use Chordy to locate and collect 10 valuable salvage in Maldraxxus. Progress: Did we find anything good?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Something Old, Something Used"},
[58437] = {id=58437,name="Parts to a Whole",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,description="Damien has some great dreams, but without more abominations, this training facility will not succeed! I have a plan though! If we can't recruit more abominations, then we shall make them ourselves! I need you to make some corpses, then mark them for harvesting with a flag. I will do the rest.",objectivesText="Mark 15 corpses for harvesting",questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=161288,text="Corpses marked for harvest"}},worldTaskTitle="Parts to a Whole",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
