[58609] = {id=58609,name="Taking The Seat",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="A wise choice, . Under your command, we will restore honor and glory to Maldraxxus. Your strength can change the Shadowlands for the better. Only with the Necrolords will you reach your full potential. For now, make your way to the Seat of the Primus. Baroness Draka will meet you there and guide you further.",objectivesText="Report to Baroness Draka at the Seat of the Primus in Maldraxxus.",starts={{x=0.429,y=0.741,mapID=1670,npcID=171821}},ends={{npcID=158453,x=0.496,y=0.224,zoneID=12876}},coords={mapID=1670,x=0.429,y=0.741},questType="world",worldTaskTitle="Taking The Seat"},
