[59603] = {id=59603,name="In Shadowlands Service",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="As Maldraxxi, we are responsible for ensuring the security of the Shadowlands. When enemies emerge, we are the ones who face them! The threats to the Shadowlands are far more than any one of us can handle. That's where I come in. I will be your eyes on the field. Allow me to demonstrate with a simple task for Marileth, so that you may both reap the benefits of my services.",objectivesText="Use the Command Table to send Marileth on an adventure. Progress: An easy task to complete.",starts={{npcID=165321,x=0.39,y=0.48,zoneID=12876}},ends={{npcID=165321,x=0.39,y=0.48,zoneID=12876}},coords={x=0.39,y=0.48,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="In Shadowlands Service"},
[59609] = {id=59609,name="No Rest For the Dead",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Excellent work, my apprentice! You have completed your training and are now a true Necrolord. That also means you've taken on additional responsibilities. Such is the burden of genius! I believe Baroness Draka wanted to have a word with you.",objectivesText="Report to Baroness Draka .",starts={{npcID=161904,x=0.39,y=0.328,zoneID=12876}},ends={{npcID=161907,x=0.496,y=0.502,zoneID=12876}},coords={x=0.39,y=0.328,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="No Rest For the Dead"},
