[59826] = {id=59826,name="Bet On Yourself",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Dear Maw Walker... my friend... you're going to lose. Everyone knows you can't compete in the arena. The entire Challenger's Promenade knows it, the brokers in Oribos know it, even Zo'umlo knows it. I've brought in a special challenger just to prove the point. Face Mistress Dyrax in the Theater of Pain and prove us wrong... or prove us right. We will be betting, so don't disappoint.",objectivesText="Defeat Mistress Dyrax in the Theater of Pain, when she appears. Progress: What did you prove?",starts={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},ends={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},coords={x=0.536,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Bet On Yourself",db2QuestInfoID=1,db2QuestInfoName="Group"},
