[59867] = {id=59867,name="WANTED: Appraiser Vix",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="For failure to pay debts upon lost wagers, theft of arena property, and for the slaughter of an authorized debt collector. All necessary violence is hereby sanctioned when confronting Vix. Special warning to be on the lookout for numerous associates who have demonstrated a violent attitude toward outsiders. Elimination of this felon is of the highest priority.",objectivesText="Eliminate Appraiser Vix Progress: Eliminate Appraiser Vix .",starts={{npcID=349612,x=0.542,y=0.475,zoneID=11462}},ends={{npcID=159830,x=0.536,y=0.474,zoneID=11462}},coords={x=0.542,y=0.475,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="WANTED: Appraiser Vix",db2QuestInfoID=1,db2QuestInfoName="Group"},
