[60110] = {id=60110,name="Never Had a Friend Like Me",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="I feel like you could use a little help, Maw Walker. There is knowledge I have which could make you more useful to the Necrolords. So just this once... I will teach you something and you won't even have to lose a limb. Soulbind with me and we'll see if you can learn anything.",objectivesText="Complete the soulbinding ritual.",starts={{npcID=161906,x=0.386,y=0.362,zoneID=12876}},ends={{npcID=161906,x=0.386,y=0.362,zoneID=12876}},coords={x=0.386,y=0.362,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Never Had a Friend Like Me"},
[60111] = {id=60111,name="Forging A Friendship",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="When you first arrived I was uncertain of your potential. The Primus demands such perfection in his work... and you are far from perfect. I see now that you bring new knowledge and ideas to our house. Your actions make us stronger. The Primus would be proud of you and wish for us all to learn from you. I am ready now to know your ways. Let me soulbind with you now, so we can grow stronger together.",objectivesText="Complete the soulbinding ritual.",starts={{npcID=161905,x=0.424,y=0.324,zoneID=12876}},ends={{npcID=161905,x=0.424,y=0.324,zoneID=12876}},coords={x=0.424,y=0.324,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Forging A Friendship"},
[60231] = {id=60231,name="State of Decay",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Kill Slimed enemies or Players",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Kill Slimed enemies or Players"}},worldTaskTitle="State of Decay",db2QuestInfoID=113,db2QuestInfoName="PvP World Quest"},
[60236] = {id=60236,name="RSVP: Cryptkeeper Kassir",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8721,mapID=1525,description="I would be most honored to attend Prince Renathal's Ember Court. I prefer to wear my official signet ring for such prestigious occasions. It was given to me by the Accuser herself when I was first charged with my duties. However, the Lord Chamberlain's goons have stolen it once more. They hide their ill-gotten gains inside of these crypts... But I have no idea which one houses my ring. It may take some time to find Atonement Crypt Keys, but any venthyr here in the halls could have one.",objectivesText="Collect Atonement Crypt Keys from venthyr around the Halls of Atonement and open Atonement Crypts until you find the Lost Cryptkeeper's Ring . Progress: Desired objects tend to be in the last place we look, do they not? Perhaps we shall be fortunate this time.",starts={{npcID=163073,x=0.702,y=0.562,zoneID=10413}},ends={{npcID=163073,x=0.702,y=0.562,zoneID=10413}},coords={x=0.702,y=0.562,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="RSVP: Cryptkeeper Kassir"},
[60291] = {id=60291,name="Corpse Run",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?",objectivesText="Return the Bone Carcass to Rathan at Butcher Block. Progress: Did you bring back the carcass?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=158300,x=0.542,y=0.68,zoneID=11462},{npcID=158300,x=0.332,y=0.546,zoneID=11400}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Corpse Run"},
[60337] = {id=60337,name="Pupa Trooper",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Borrow a pair of enchanted wings",questType="world",db2Objectives={{orderIndex=0,type=2,amount=1,objectID=365342,text="Borrow a pair of enchanted wings"}},worldTaskTitle="Pupa Trooper",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60358] = {id=60358,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Took our gildenite ! Stole it! Stole it and took it away! Need it, need it to make armor! Weapons! Can't make armor without gildenite ! You understand? Yes? Why you still here?",objectivesText="Collect 3 Gildenite from rare monsters and treasure chests in Bastion.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60363] = {id=60363,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Hshh... the golden ore, we need it. Golden ore of Bastion. Make their armor with it. We need, many uses. Armors, weapons, trinkets and rings. Many uses. Travel to Bastion. The eyes have shown me stores of it, stolen and hidden throughout their lands. They do not use it. We will. Go now.",objectivesText="Collect 3 Gildenite from rare monsters and treasure chests in Bastion.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60364] = {id=60364,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="Our allies in Bastion are in possession of a special ore known as gildenite . A golden metal used for many things in their lands, it is also useful to us. Once upon a time, we would have traded for it. Now, we have little to trade, and they have little to give. Yet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it. Should you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.",objectivesText="Collect 3 Gildenite from rare monsters and treasure chests in Bastion.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60365] = {id=60365,name="Gildenite Grab",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well. Our stores are nearly depleted, and we have little to trade, but our needs are great. Let us reflect. In Bastion, there are those that have turned their backs on their own people. We may relieve these deceivers of their gildenite without remorse.",objectivesText="Collect 3 Gildenite from rare monsters and treasure chests in Bastion.",questType="world",worldTaskTitle="Gildenite Grab",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60369] = {id=60369,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="The shapers of our lands cultivate a very special form of wood we call wealdwood . It contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn. It is the basis of our arms and armor, and in these dark days, it is a target of our enemies. They steal and hoard it, out there in the wilds. Find them, and return our treasures to us.",objectivesText="Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60370] = {id=60370,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood , an enchanted substance used for many sorcerous purposes, is a key component in our rituals. Without it, our magics pale in comparison to those of our enemies. Yet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places. Travel to those places, and return to us once you have brought atonement to these vile creatures.",objectivesText="Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60371] = {id=60371,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="The eyes have shown me supplies, in Ardenweald. Hidden in the boughs, hidden from us, but they cannot hide from the eyes. They do not use it, not as we would. We must use it. It is ours to take. Kshhhh... bring it to us, the shaped wood. Many uses, very magical. Holds magic as a pitcher holds slime, fills with it. Need it for our sorcerers. Cannot win in battle without our magic. Must win, no other way.",objectivesText="Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60372] = {id=60372,name="A Wealth of Wealdwood",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood . wealdwood magical, help us make many thing. You find some? Bring to Sika? Yes? Hoo? Yes. See?",objectivesText="Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.",questType="world",worldTaskTitle="A Wealth of Wealdwood",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60373] = {id=60373,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="There is a dark, evil vine that grows in Revendreth, known as sorrowvine . They say it feeds off of the anguish of the souls as they are broken. Regardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin. Revendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.",objectivesText="Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60374] = {id=60374,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1565,description="The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones. They form their armors out of a cultivated form of bone we call bonemetal . Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength. We have many uses for it, both as a means of attachment, and when ground up, as a reagent. We cannot ask them for resources now, but if you find any, I would use it.",objectivesText="Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60375] = {id=60375,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="Maldraxxus no longer answers our calls, and the houses are in disarray. Yet we have need of them. Once, they supplied us with bonemetal , a strong yet malleable material useful for many armors. There are those in Maldraxxus that hoard the material, seeking to profit from the chaos. They must atone for these sins.",objectivesText="Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60376] = {id=60376,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Ksh-ksh-ksh... you are needed. So many betrayers in our lands, many deaths, much armor destroyed. Need to rebuild. The eyes have shown me stores of bonemetal , hoarded by our foes. Bring them to me.",objectivesText="Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60377] = {id=60377,name="Bonemetal Bonanza",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="No bonemetal ! Again, out of bonemetal ! Hoo! Where you come from? Oh, OH. bonemetal ! You get? Get from Maldraxxus. Help us out! That way!",objectivesText="Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.",questType="world",worldTaskTitle="Bonemetal Bonanza",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60378] = {id=60378,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins. We use it for many things, from potions to venoms. It is a versatile reagent. Our stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us. As you travel our lands, should you come upon any, we would make good use of it.",objectivesText="Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60379] = {id=60379,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms. Revendreth does not answer our calls. The eyes show me conflict and strife in their lands. This matters little to us. Shh... travel there, find their vines, return to me.",objectivesText="Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60380] = {id=60380,name="A Source of Sorrowvine",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Need sorrowvine ! Please help! Revendreth not sending us supplies, not answering Sika! Can't make potions now. What we do? You go! Go go!",objectivesText="Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.",questType="world",worldTaskTitle="A Source of Sorrowvine",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60381] = {id=60381,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides. Travel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall. Remind them that our great purpose will be fulfilled, and we will not let the groves wither. You, Maw Walker, will unite us today.",objectivesText="Complete 3 World Quests in Ardenweald. Progress: Have you brought hope and faith to our people today?",starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60382] = {id=60382,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="We do not turn out backs on our allies, even when we face darkness here in Ardenweald. In Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader. We cannot allow those that make Sinfall their home to lose hope. Travel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.",objectivesText="Complete 3 World Quests in Revendreth. Progress: How goes the battle in Revendreth?",starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60383] = {id=60383,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did. Now they are plagued by infighting and an imbalance in power. We have few allies there, but those that remain, we must maintain. Go there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more. Without them, we are but one invasion from complete annihilation.",objectivesText="Complete 3 World Quests in Maldraxxus. Progress: Have you aided the forces of Maldraxxus?",starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60384] = {id=60384,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die. We cannot allow them to fall, for without Bastion, we are lost. Travel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.",objectivesText="Complete 3 World Quests in Bastion. Progress: Have you aided Bastion today?",starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60385] = {id=60385,name="Training in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training. Come here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt. For tomorrow, we hunt.",objectivesText="Complete 3 World Quests in Revendreth with your trainee.",starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60386] = {id=60386,name="Training in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves. There is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields. Take this one with you on your travels today, so that they may see what real combat looks like.",objectivesText="Complete 3 World Quests in Maldraxxus with your trainee. Progress: Do you return with a trainee, or a coward?",starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60387] = {id=60387,name="Training in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Our hunters do not have the time for proper training, and so we must train them in the field. Our allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor. Do you hear that, trainee? Today, you accompany the Maw Walker! Maw Walker, do not go easy on this one.",objectivesText="Complete 3 World Quests in Bastion with your trainee. Progress: I hope that today's trainee survived the trip, but I am not overly confident.",starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60388] = {id=60388,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Get up, trainee, you must get up! Look at this one! Needs much more training before we stand a fighting chance against our enemies. We have precious little time to build combat prowess these days, with so many foes at our backs. Take this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.",objectivesText="Complete 3 World Quests in Ardenweald with your trainee. Progress: How goes the training?",starts={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},ends={{npcID=158544,x=0.478,y=0.536,zoneID=11510}},coords={x=0.478,y=0.536,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60389] = {id=60389,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Ay there, ya got a moment? Lotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one. We're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? Do I gotta spell it out for you? Get on over there, ya big goof.",objectivesText="Complete 3 World Quests in Ardenweald.",starts={{x=0.622,y=0.763,mapID=1700,npcID=165302}},ends={{x=0.622,y=0.763,mapID=1700,npcID=165302}},coords={mapID=1700,x=0.622,y=0.763},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60390] = {id=60390,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We are attacked by enemies on all sides, Maw Walker. And Ardenweald faces a similar threat. It is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need. Together, we are strong. This is the doctrine of the phalanx, and it will be ours as well.",objectivesText="Complete 3 World Quests in Ardenweald. Progress: Have you secured allies in Ardenweald?",starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60391] = {id=60391,name="Aiding Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall! Make haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone! Bastion stands with them, and with us, they will never falter!",objectivesText="Complete 3 World Quests in Ardenweald. Progress: Have you served in Ardenweald today?",starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60392] = {id=60392,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="In our own golden hills, evil abounds. We will not allow it to take root and fester! Raise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them! With haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon! For Bastion!",objectivesText="Complete 3 World Quests in Bastion. Progress: Do the hills echo with the cries of your victories, Maw Walker?",starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60393] = {id=60393,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them. Travel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies. War is not always fought on the battlefield, but often in the means of replenishment.",objectivesText="Complete 3 World Quests in Bastion. Progress: Have you secured the situation in Bastion?",starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60394] = {id=60394,name="Aiding Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better. We got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff. Rendle wipes his nose loudly.>",objectivesText="Complete 3 World Quests in Bastion.",starts={{x=0.62,y=0.762,mapID=1700,npcID=165302}},ends={{x=0.62,y=0.762,mapID=1700,npcID=165302}},coords={mapID=1700,x=0.62,y=0.762},questType="world",worldTaskTitle="Aiding Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60395] = {id=60395,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all. We must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord. A spear of gold and bone we will form! And thrust it into the heart of evil! Go now, Maw Walker, as the tip of the spear, to glorious battle!",objectivesText="Complete 3 World Quests in Maldraxxus. Progress: Have you pierced the heart of evil in Maldraxxus?",starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60396] = {id=60396,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand. Walk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you. Fear is the seed that breeds doubt, and doubt is the root that crumbles empires.",objectivesText="Complete 3 World Quests in Maldraxxus. Progress: How goes the battle?",starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60397] = {id=60397,name="Aiding Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left. All's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out. Get over there and help them good ones keep the peace, maybe they help us out some day, too.",objectivesText="Complete 3 World Quests in Maldraxxus.",starts={{x=0.62,y=0.761,mapID=1700,npcID=165302}},ends={{x=0.62,y=0.761,mapID=1700,npcID=165302}},coords={mapID=1700,x=0.62,y=0.761},questType="world",worldTaskTitle="Aiding Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60398] = {id=60398,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. Once, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses. Today, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part. It is your Primus-given duty to aid Sinfall against those that seek to break the cycle.",objectivesText="Complete 3 World Quests in Revendreth. Progress: Have you broken the forces of Denathrius?",starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60399] = {id=60399,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Oi there, got somethin' for you to do today. Lots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems. We're not gonna make much headway against Denathrius with his lot at our heels all the time, ay? Get out there an' get some muck on your boots.",objectivesText="Complete 3 World Quests in Revendreth. Progress: What do ya want?",starts={{x=0.622,y=0.763,mapID=1700,npcID=165302}},ends={{x=0.622,y=0.763,mapID=1700,npcID=165302}},coords={mapID=1700,x=0.622,y=0.763},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60400] = {id=60400,name="Aiding Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius. We cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all. We of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!",objectivesText="Complete 3 World Quests in Revendreth.",starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Aiding Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60401] = {id=60401,name="Training in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. Plenty of things to maim over there, maybe they learn a thing or two about wood.",objectivesText="Complete 3 World Quests in Ardenweald with your trainee.",starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60402] = {id=60402,name="Training in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads. Take this trainee out and get them some real combat experience. Ardenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.",objectivesText="Complete 3 World Quests in Ardenweald with your trainee. Progress: You back already?",starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60403] = {id=60403,name="Training in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="It is our great duty to take our aspiring warriors and train them in combat. Today, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands. Teach them the ways of battle and honor.",objectivesText="Complete 3 World Quests in Ardenweald with your trainee. Progress: How fares the training?",starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60404] = {id=60404,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="What better place to stretch our wings than right here on our own fields? Take one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here. Part of their training will be courage when facing off against those they thought their brethren. It has been known to break hearts and ranks before.",objectivesText="Complete 3 World Quests in Bastion with your trainee. Progress: How fares your heart today?",starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60405] = {id=60405,name="Training in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Useless minions, the lot of them. All of this fodder needs to get trained. Here, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me. Plenty of things to test them against, there. If you get them killed, I don't want to hear it.",objectivesText="Complete 3 World Quests in Bastion with your trainee. Progress: Any luck with this sad lot?",starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60406] = {id=60406,name="Training in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have yet another minion, er, recruit that needs training. Take them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. Maybe you pick up some new tricks while you're out there, too.",objectivesText="Complete 3 World Quests in Bastion with your trainee.",starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60407] = {id=60407,name="Training in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath. Take this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators. There, they will face true challenges, and return with great knowledge.",objectivesText="Complete 3 World Quests in Maldraxxus with your trainee. Progress: Has your trainee survived the fields of battle?",starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60408] = {id=60408,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat. Take a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.",objectivesText="Complete 3 World Quests in Maldraxxus with your trainee. Progress: Any luck out there?",starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60409] = {id=60409,name="Training in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Another trainee needs some looking after, if you don't mind. Maldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that. Just throw them in the arena or something. 'Sink or swim' is an effective training strategy.",objectivesText="Complete 3 World Quests in Maldraxxus with your trainee. Progress: Could really go for a nap I could.",starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60410] = {id=60410,name="Training Our Forces",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="I have yet more troops for you to train, and there are plenty of things to do right here in our domain. Take them out and give them a good, solid, and probably bloody taste of what we're up against. Now, if you get them killed? That's none of my business.",objectivesText="Complete 3 World Quests in Revendreth with your trainee. Progress: Did you manage to bring them back alive?",starts={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},ends={{npcID=164741,x=0.578,y=0.588,zoneID=10986}},coords={x=0.578,y=0.588,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Training Our Forces",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60411] = {id=60411,name="Training in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking. Do me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic. Won't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.",objectivesText="Complete 3 World Quests in Revendreth with your trainee. Progress: Well? You bring back a pile of bones or a trainee?",starts={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},ends={{npcID=167209,x=0.514,y=0.292,zoneID=12876}},coords={x=0.514,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Training in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60412] = {id=60412,name="Training in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="A trainee is in need of your guiding hand. Take them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes. Return victorious, as their shield and mentor, so that our armies will be bolstered this day.",objectivesText="Complete 3 World Quests in Revendreth with your trainee.",starts={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.374,y=0.61,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Training in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60414] = {id=60414,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1701,description="The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. We have relied upon them to bring us useful materials for many years, but these days, we have little to trade. They value a currency of their own making, coins of brokerage, as a general means of trade. If you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.",objectivesText="Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Have you found any coins?",starts={{npcID=168513,x=0.436,y=0.524,zoneID=11510}},ends={{npcID=168513,x=0.436,y=0.524,zoneID=11510}},coords={x=0.436,y=0.524,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60415] = {id=60415,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Hello! Yes! Hello. Brokers, you know them? Sika does her best attempt at looking like a broker. It is not convincing.> Trade many things with us. Things we no get. Things we want. Need coins. Clink clink! Sika makes a circle with her finger feathers.> Find them everywhere, bring them to Sika !",objectivesText="Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Bring coins to Sika ? Need trade with brokers. You know this?",starts={{npcID=168519,x=0.634,y=0.168,zoneID=10534},{npcID=168519,x=0.334,y=0.448,zoneID=11012}},ends={{npcID=168519,x=0.634,y=0.168,zoneID=10534},{npcID=168519,x=0.334,y=0.448,zoneID=11012}},coords={x=0.634,y=0.168,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60416] = {id=60416,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them. Find many secrets, they do. Bring us supplies, strange and rare. Need things to trade. Need broker coins. They trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. You may eat their corpses, I will not judge. Just need coins.",objectivesText="Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Bring me coins? Coins for brokers. Many uses. You see?",starts={{npcID=167201,x=0.47,y=0.384,zoneID=12876}},ends={{npcID=167201,x=0.47,y=0.384,zoneID=12876}},coords={x=0.47,y=0.384,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60417] = {id=60417,name="Rare Resources",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13400,mapID=1700,description="The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure. They are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere. They hold in high regard a currency of their own creation, you may find such coins in your travels. I will gladly take them off of your hands to bolster our supplies.",objectivesText="Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Have you found any of the broker's coins?",starts={{npcID=158713,x=0.248,y=0.562,zoneID=10986},{npcID=158713,x=0.608,y=0.664,zoneID=10986}},ends={{npcID=158713,x=0.248,y=0.562,zoneID=10986},{npcID=158713,x=0.608,y=0.664,zoneID=10986}},coords={x=0.248,y=0.562,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Rare Resources",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60418] = {id=60418,name="A Call to Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1701,description="Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. If they fall to darkness, it's only a matter of time before we, too, dwindle and fade. They are beset by all manner of problems. We have to get over there and help them!",objectivesText="Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: How are the Kyrians?",starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Call to Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60419] = {id=60419,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1701,description="They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! All throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect. If the cycle stops here, so many great souls will be lost... forever. There's no time to waste, we need your help! Defend Ardenweald!",objectivesText="Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Are things improving in the glades?",starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60420] = {id=60420,name="A Call to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1701,description="I'm glad you're here! We've got some problems in Maldraxxus. The forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. But now, some of the houses have overthrown the balance, and seek to conquer the rest of us! Our allies there need our help! Aid them however you can.",objectivesText="Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons. Progress: Are things improving in Maldraxxus?",starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Call to Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60421] = {id=60421,name="A Call to Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1701,description="Oh, I'm glad you're here, we've got a problem! Our friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! If Denathrius's control of Revendreth isn't broken, he'll come for us next... Let's do whatever we can to help them out!",objectivesText="Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: How are things in Revendreth?",starts={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},ends={{npcID=167193,x=0.598,y=0.324,zoneID=12858},{npcID=167193,x=0.598,y=0.324,zoneID=12858}},coords={x=0.598,y=0.324,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Call to Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60422] = {id=60422,name="A Call to Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1699,description="We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger. The great soul-trees of Ardenweald are under assault from many foes that seek to harness their power. We must aid our allies in the Night Fae, and punish their enemies for these transgressions. We are stronger together.",objectivesText="Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Have you completed your task?",starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="A Call to Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60423] = {id=60423,name="A Call to Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1698,description="Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. Maldraxxus alone is responsible for challenging those that would disrupt the cycle. Take our banners, steady your weapons, and bring war to Ardenweald. For the Shadowlands.",objectivesText="Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: How do the boughs break?",starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Call to Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60424] = {id=60424,name="A Call to Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13334,mapID=1707,description="Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls. Should the weald fall, the devastation that would be unleashed could destroy us all. We must aid the Winter Queen. It is the will of the Archon. Go now, and provide support to the Night Fae.",objectivesText="Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Have things improved in Ardenweald?",starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="A Call to Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60425] = {id=60425,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1707,description="Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes. Today, we root them out. Head into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you. In the name of the Archon.",objectivesText="Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Are the fields cleansed?",starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60426] = {id=60426,name="A Call to Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1698,description="We, the defenders of the Shadowlands, will never let a great foe go unchallenged. The Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services. Now, they too are under attack from within. We must defend them in their time of need. Go now, and bring glory in the name of the Primus.",objectivesText="Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Are the golden fields bathed in blood?",starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Call to Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60427] = {id=60427,name="A Call to Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12916,mapID=1699,description="The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger. They have their own troubles in these times, as well. Today, we must look without, and aid our allies. Travel to the golden fields, and rid them of their foes. Only with allies do we stand a chance against Denathrius.",objectivesText="Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Have you completed your task?",starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="A Call to Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60429] = {id=60429,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1698,description="Look! Look around you! All around us, foes await the crushing hand of victory. There is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened. The only cure is more combat! Challenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.",objectivesText="Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons. Progress: Have you littered the ground with the bones of your enemies?",starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60430] = {id=60430,name="A Call to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1707,description="The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands. Now, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others. Their problems are many, our solutions are just. Travel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.",objectivesText="Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.",starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="A Call to Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60431] = {id=60431,name="A Call to Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=16535,mapID=1699,description="The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now. The houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten. Go now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.",objectivesText="Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.",starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="A Call to Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60432] = {id=60432,name="Troubles at Home",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1699,description="There are many tasks that need your attention outside of the walls of Sinfall. Our closest allies are under assault from all sides, and the forces of Denathrius are unrelenting. Take your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies. We will take back what is ours.",objectivesText="Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: Have you reclaimed our homeland?",starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Troubles at Home",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60433] = {id=60433,name="A Call to Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1698,description="We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls. There is one such betrayer - Sire Denathrius. Bring the vengeance of Maldraxxus down upon his foul crown. Slay his allies, serve his foes, end his reign in carnage.",objectivesText="Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: How fares the battle for Revendreth?",starts={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},ends={{npcID=167210,x=0.594,y=0.438,zoneID=12876}},coords={x=0.594,y=0.438,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Call to Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60434] = {id=60434,name="A Call to Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13329,mapID=1707,description="We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just. Yet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands. We have friends there, amongst the Venthyr. Aid them, and put their enemies to rest. The Word of the Archon is with you.",objectivesText="Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: Have you returned victorious?",starts={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},ends={{npcID=160037,x=0.664,y=0.166,zoneID=10534},{npcID=160037,x=0.554,y=0.422,zoneID=11012}},coords={x=0.664,y=0.166,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="A Call to Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60435] = {id=60435,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors. Over many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will. What better way to secure our allies and test our strength, than to eliminate his most fervent champions. Go now, and hunt.",objectivesText="Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Have you thinned Denathrius's forces?",starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60436] = {id=60436,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands. There, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds. Crash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.",objectivesText="Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Have you returned victorious?",starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60437] = {id=60437,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls. They are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos. Doubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.",objectivesText="Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you aided the denizens of Bastion?",starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60438] = {id=60438,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life. In our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue. Take on this trial, and put an end to the invaders of Tirna Scithe.",objectivesText="Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: How goes the hunt?",starts={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},ends={{npcID=167206,x=0.372,y=0.258,zoneID=12858},{npcID=167206,x=0.37,y=0.258,zoneID=12858}},coords={x=0.372,y=0.258,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60439] = {id=60439,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades. Ready your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness. It is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils. Light shines only in darkness.",objectivesText="Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Have you cleansed the weald?",starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60440] = {id=60440,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no? So ready your weapon and get out there! What better place to prove your might? Smash them to pieces, in the name of Maldraxxus!",objectivesText="Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Rip and tear!",starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60441] = {id=60441,name="Challenges in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Ardenweald was once a place of peace and regrowth, but no longer. Foes assault the weald from all sides, dark creatures that serve no masters. They will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them. They will see what we do to those that must be broken. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",objectivesText="Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Has justice been served?",starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60442] = {id=60442,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Sometimes we need look no further than our own golden hills to find a suitable challenge. Doubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight. We must stand against them, now. It will not be easy, but things that are worth fighting for rarely are.",objectivesText="Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you seen the face of doubt and shown it certainty?",starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60443] = {id=60443,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle! We must aid them against their foes, or else the arena will sit barren, and we can't have that! Find their greatest enemies and turn their bones into golden dust.",objectivesText="Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you clipped their wings?",starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60444] = {id=60444,name="Challenges in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services. Yet, within their ranks, doubt has grown and festered. If this continues, we will all pay. Their loss of focus shall not be allowed to continue. We will punish their wandering hearts. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",objectivesText="Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Has justice been served?",starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60445] = {id=60445,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds. Here, you will find some of your greatest challenges. Seek out the champions of the strongest houses, stand against them, and let them see your might.",objectivesText="Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Do you stand victorious?",starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60446] = {id=60446,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds. For many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless. They must pay for these transgressions. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",objectivesText="Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Has justice been served?",starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60447] = {id=60447,name="Challenges in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors. What better place to test yourself? Head into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.",objectivesText="Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Have you found the truth in courage?",starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60448] = {id=60448,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all. Some are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. They are the mightiest of Denathrius's allies, and they must be brought to justice. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.",objectivesText="Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Has justice been served?",starts={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},ends={{npcID=165291,x=0.436,y=0.516,zoneID=10413}},coords={x=0.436,y=0.516,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60449] = {id=60449,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out. Their leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right. I want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.",objectivesText="Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: You didn't let them bite you, right?",starts={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},ends={{npcID=167208,x=0.568,y=0.442,zoneID=12876}},coords={x=0.568,y=0.442,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60450] = {id=60450,name="Challenges in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? In this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield. None more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands. And here is where you must challenge yourself today.",objectivesText="Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Have you proven your worth in Revendreth?",starts={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},ends={{npcID=154627,x=0.618,y=0.378,zoneID=11012}},coords={x=0.618,y=0.378,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="Challenges in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60452] = {id=60452,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it! You need to go back there! You're the Maw Walker! See what you can learn of his power, and slow him down however you can. I believe in you! Be careful, ok?",objectivesText="Kill 3 rare or special encounter bosses in The Maw.",starts={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},ends={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60454] = {id=60454,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this. We know little about the Jailer's lands, save that he is powerful beyond imagining. I ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces. We must buy more time.",objectivesText="Kill 3 rare or special encounter bosses in The Maw.",starts={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},ends={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60455] = {id=60455,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall. Return to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day. His forces must be slowed, make what progress you can.",objectivesText="Kill 3 rare or special encounter bosses in The Maw. Progress: You seem different, somehow.",starts={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},ends={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},coords={x=0.432,y=0.472,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60456] = {id=60456,name="Storm the Maw",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return. What I am about to ask of you I would not dare ask of another. We cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands. Make what progress you can, we must slow down his forces however possible.",objectivesText="Kill 3 rare or special encounter bosses in The Maw.",starts={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},ends={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Storm the Maw",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60457] = {id=60457,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it. Maw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower. Bring us that which we lack.",objectivesText="Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you recovered the Anima Embers ?",starts={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},ends={{npcID=158553,x=0.342,y=0.436,zoneID=12858},{npcID=158553,x=0.342,y=0.436,zoneID=12858}},coords={x=0.342,y=0.436,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60458] = {id=60458,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands. Souls that have been devoured, consumed, their anima lost to us. Return to us what you can.",objectivesText="Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you secured the lost Anima Embers ?",starts={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},ends={{npcID=160212,x=0.67,y=0.154,zoneID=10534}},coords={x=0.67,y=0.154,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60459] = {id=60459,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus. The Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops. Travel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.",objectivesText="Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you brought Anima Embers for our stockpiles?",starts={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},ends={{npcID=167207,x=0.432,y=0.472,zoneID=12876}},coords={x=0.432,y=0.472,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60460] = {id=60460,name="Anima Salvage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1699,description="Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society. This is a necessary part of the cycle. Yet now, the cycle is broken, and are unable to serve our great purpose. In order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.",objectivesText="Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you brought the Anima Embers to us?",starts={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},ends={{npcID=164738,x=0.46,y=0.284,zoneID=10986}},coords={x=0.46,y=0.284,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Anima Salvage",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60462] = {id=60462,name="Anima Appeal",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1702,description="Maw Walker! The Anima Reservoir is nearly depleted. Without more anima, the groves shall soon wither and die. Search the realms for additional nourishment and deliver it to the sanctum. Ardenweald cannot continue without your aid!",objectivesText="Deposit 600 anima in the Anima Reservoir at the Heart of the Forest in Ardenweald.",starts={{x=0.489,y=0.393,mapID=1565,npcID=167196}},ends={{x=0.489,y=0.393,mapID=1565,npcID=167196}},coords={mapID=1565,x=0.489,y=0.393},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60463] = {id=60463,name="Anima Appeal",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1700,description="Maw Walker! Our anima stores have run low, and soon we will have nothing to sate our thirst... Seek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum. These are dire circumstances. Our fate is in your hands.",objectivesText="Deposit 600 anima in the Anima Reservoir at Sinfall in Revendreth.",questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60464] = {id=60464,name="Anima Appeal",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,description="Maw Walker! Our anima reserves are nearly depleted. Without an additional supply of anima, our mission of conquest will be lost! Scour the realms for all the anima you can gather and deliver it here to the sanctum. Victory depends on your success!",objectivesText="Deposit 600 anima in the Anima Reservoir at Seat of the Primus in Maldraxxus.",starts={{npcID=167205}},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[60465] = {id=60465,name="Anima Appeal",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1707,description="Maw Walker! Our supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late! Search the realms for all the anima you can gather and deliver it to the sanctum. Time is short. Move swiftly, .",objectivesText="Deposit 600 anima in the Anima Reservoir at Elysian Hold in Bastion.",starts={{x=0.64,y=0.2,mapID=1533,npcID=158773}},ends={{x=0.64,y=0.2,mapID=1533,npcID=158773}},coords={mapID=1533,x=0.64,y=0.2},questType="world",worldTaskTitle="Anima Appeal",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
