[60609] = {id=60609,name="Who Devours the Devourers?",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Devourer Rifts closed Resonating Anima Core created from motes",questType="world",db2Objectives={{orderIndex=0,type=0,amount=5,objectID=169444,text="Devourer Rifts closed"},{orderIndex=1,type=0,amount=1,objectID=175539,text="Resonating Anima Core created from motes"}},worldTaskTitle="Who Devours the Devourers?",db2QuestInfoID=111,db2QuestInfoName="Elite World Quest"},
[60622] = {id=60622,name="Eye of the Scryer",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Evading the Mawsworn's scryers requires powerful magical countermeasures. The prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance. The scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye. Restraint is advised in its procurement.",objectivesText="Obtain the Eye of the Scryer from Leerok the Scryer in The Maw . Progress: Well? Do you have it, undamaged?",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Eye of the Scryer"},
[60623] = {id=60623,name="AHHH! Real Monsters!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="Repel the Devourer threat",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Repel the Devourer threat"}},worldTaskTitle="AHHH! Real Monsters!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60646] = {id=60646,name="Misery Business",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn have begun harvesting the misery of the souls flowing through Gorgoa, the river of souls. Why? I do not know yet. But it behooves us to stop them. Destroy the conduits that they deposit the misery into and bring me some samples of their work. Perhaps with some research, I can discern their intentions.",objectivesText="Collect 10 Essences of Misery and destroy the Misery Conduits. Progress: Have you halted their misery?",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Misery Business"},
