[60732] = {id=60732,name="Disrupting the Flow",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served. The complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done. Send the inhabitants of Zovaal's Cauldron a message.>",objectivesText="Disrupt the Mawsworn's efforts in Zovaal's Cauldron.",starts={{npcID=176164,x=0.394,y=0.458,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.394,y=0.458,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Disrupting the Flow"},
[60739] = {id=60739,name="Tough Crowd",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,questType="world",worldTaskTitle="Tough Crowd",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60762] = {id=60762,name="Death Motes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="I have a task for you, Maw Walker. Souls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will. It is a tragic end. I wish to better understand this process--what is it about a soul that causes this transformation? Fragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.",objectivesText="Collect 10 Death Motes from Ruin's Cradle in The Maw .",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Death Motes"},
[60770] = {id=60770,name="Squish and Burn",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Gorm eggs burned Larvae squished",questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=170239,text="Gorm eggs burned"},{orderIndex=1,type=0,amount=50,objectID=170240,text="Larvae squished"}},worldTaskTitle="Squish and Burn",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60775] = {id=60775,name="A Suitable Demise",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy. The soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain. This of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.",objectivesText="Throw 5 Soulforged Cores into Soulforges in Zovaal's Cauldron in the Maw .",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Suitable Demise"},
