[60948] = {id=60948,name="RSVP: The Countess",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Prince wishes to host court? Well, that should be interesting... I am sure you understand that one musn't give without receiving something of value in return. It sets a terrible precedent, provides unrealistic expectations, and encourages beggars. So you shall do something for me. House Briarbane is very proud of their new mascot. They have been flaunting it in the streets and irritating the other houses. Steal it for me, but incriminate one of the other houses in the act.",objectivesText="Disguise yourself as a member of House Iremoore and steal the House Briarbane mascot. Progress: It would be a shame to waste such a fine mascot on such an unworthy house.",starts={{npcID=171106,x=0.58,y=0.276,zoneID=10413}},ends={{npcID=171106,x=0.58,y=0.276,zoneID=10413}},coords={x=0.58,y=0.276,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="RSVP: The Countess"},
[60950] = {id=60950,name="A Matter of Stealth",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Obtain Disguise from Amberfoot Fallen Sylvar Enraged",questType="world",db2Objectives={{orderIndex=1,type=0,amount=6,objectID=170791,text="Fallen Sylvar Enraged"},{orderIndex=0,type=0,amount=1,objectID=170928,text="Obtain Disguise from Amberfoot"}},worldTaskTitle="A Matter of Stealth",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[60958] = {id=60958,name="We Send Only You",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="House of Constructs forces disrupted",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="House of Constructs forces disrupted"}},worldTaskTitle="We Send Only You",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61059] = {id=61059,name="RSVP: Rendle and Cudgelface",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="I heard about the prince wanting Rendle and me at 'is court. I aim to please 'im an all, but Rendle says 'e haven't got proper ah-tire. Says 'e needs a sootible hat, maybe somethin' posh that hints at 'is inner depths. He says the only good hats are: Red Noggin Candle, or one a them Fae Revel Masques. Or mebbe a Pink Party Hat, or a fancy Crown o' the Righteous.",objectivesText="\"Sootible\" hats may be crafted by players who have the recipe and appropriate tradeskill.",starts={{x=0.619,y=0.77,mapID=1700,npcID=171190}},ends={{x=0.619,y=0.77,mapID=1700,npcID=171190}},coords={mapID=1700,x=0.619,y=0.77},questType="world",worldTaskTitle="RSVP: Rendle and Cudgelface"},
[61060] = {id=61060,name="Spore Losers",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Fungret Mushroom eaten Revenge for Fungrets Rally Fungret",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=171115,text="Fungret Mushroom eaten"},{orderIndex=1,type=15,amount=1,objectID=0,text="Revenge for Fungrets"},{orderIndex=3,type=0,amount=50,objectID=171140,text="Rally Fungret"}},worldTaskTitle="Spore Losers",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61062] = {id=61062,name="Adjutant Dekaris",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,questType="world",worldTaskTitle="Adjutant Dekaris"},
[61075] = {id=61075,name="A Spark of Light",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Gorgoa is a protean force fueled by souls that trickle in from many worlds. They wash in from the head of the river, a place they have named the Crucible of the Damned. The Jailer's unblinking eyes patrol the river and watch for souls who attempt escape. Blind the eyes that find them. Close them for good. Take this and do what must be done.",objectivesText="Defeat 4 Eyes of Damnation. Progress: Have you closed the Jailer's eyes?",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Spark of Light"},
[61079] = {id=61079,name="The Jailer's Share",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn's torturers have a talent for misery. The suffering they inflict often produces more stygia than they can collect. The excess floats loosely in the air, left to drift into the abyss. I have fashioned a conduit specifically for capturing the leftover stygia . You can borrow it if you wish. There are a handful of prime gathering locations throughout Calcis. As you'll be using my conduits, we can split what you find upon your return.",objectivesText="Place 4 Stygia Conduits at marked locations within Calcis in The Maw . Progress: Were the conduits effective? How much stygia did they collect?",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="The Jailer's Share"},
[61088] = {id=61088,name="Dust to Dust",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn never cease to invent new forms of suffering. Even the ground on which we tread is formed from souls pounded into dust. With the flood of souls passing through Gorgoa, the Mawsworn are keen to expand their domain. At present, the Mawsworn are burying souls and crafting new terrain from their torment. It is not too late for some of them. Free the buried souls and stop the endless expansion of suffering.",starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Dust to Dust"},
[61092] = {id=61092,name="RSVP: Grandmaster Vole",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I'm busy, so I'll get right to the point. The only way I'm going is if you pay me enough coin to make it worth my while or you amuse me. As interesting and enjoyable as the Ember Court may be, I lose money every time I am away from here. That said, I do love a good slaughter. So, coin or deaths. Take your pick.",objectivesText="Convince Grandmaster Vole by bribing him or slaying players of the opposite faction. Progress: You need to cough up the coin or get killing.",starts={{npcID=163019,x=0.528,y=0.492,zoneID=11462}},ends={{npcID=163019,x=0.528,y=0.492,zoneID=11462}},coords={x=0.528,y=0.492,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Grandmaster Vole"},
[61103] = {id=61103,name="Disrupting the Cycle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The shacklers in the Tremaculum are an awful sort. Souls are tortured there until they turn malevolent. They are then outfitted as guards so the cycle can continue. If you wish to slow the rate at which the Jailer raises his armies, start at the source. Disrupt the cycle at the Tremaculum.",objectivesText="Defeat 4 Mawsworn Shacklers and 6 Deadeyes at the Tremaculum in The Maw .",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Disrupting the Cycle"},
[61104] = {id=61104,name="Grathalax, the Extractor",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13587,mapID=1543,description="There are many powerful lieutenants among the Mawsworn, but there is one who is particularly important to the Jailer. Far beneath the Tremaculum lives the Jailer's prime interrogator, Grathalax . Power is fed to him via conduits throughout the area. His role is to make the process of anima extraction more efficient. His methods are... unkind. I believe we would both benefit from the end of his existence.",objectivesText="Defeat Grathalax underneath the Tremaculum in The Maw .",starts={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.468,y=0.416,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Grathalax, the Extractor"},
[61105] = {id=61105,name="RSVP: Plague Deviser Marileth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Oh! This sounds like a wonderful opportunity to do field research in Revendreth, apprentice. I look forward to collaborating with new colleagues. We must bring a gift to thank them for their invitation. What could be more appropriate than some lovely slimes? Please pick some of the best slimes for me to present to our host. Just bring them to Kevin so they can make friends and travel together.",objectivesText="Herd Bubbling Oozes to Kevin so Plague Deviser Marileth has a present to bring to the Ember Court. Progress: Have you finished choosing our gift slimes yet, apprentice?",starts={{npcID=159930,x=0.604,y=0.716,zoneID=11462}},ends={{npcID=159930,x=0.604,y=0.716,zoneID=11462}},coords={x=0.604,y=0.716,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Plague Deviser Marileth"},
[61109] = {id=61109,name="RSVP: Hunt-Captain Korayn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I am a Captain of the Wild Hunt, a defender of the sacred groves. As much as I would enjoy the diversion, my place is here fighting back the forces of the enemy, not venturing outside of Ardenweald. Eggs are hatching again at Gormhive and we shall soon be overrun by gormling larva. Until that threat is neutralized I cannot leave my post.",objectivesText="Remove the threat of Gormhive by smashing eggs, eliminating egg tenders, and slaying gorm so Hunt-Captain Korayn can attend the Ember Court.",starts={{npcID=171319,x=0.508,y=0.704,zoneID=11510}},ends={{npcID=171319,x=0.508,y=0.704,zoneID=11510}},coords={x=0.508,y=0.704,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Hunt-Captain Korayn"},
[61123] = {id=61123,name="RSVP: Polemarch Adrestes",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="I must politely decline your Prince's offer. My skills are needed here, and I am not particularly well-suited to the social demands of attending court. Perhaps the Paragon of Humility would be a better representative for Bastion. You may find him at the Temple of Humility, east of here. Please express my sincere regrets that I am unable to attend.",objectivesText="Seek the assistance of the Paragon of Humility. Progress: My answer has not changed.",starts={{npcID=171385,x=0.69,y=0.406,zoneID=10534}},ends={{npcID=171385,x=0.69,y=0.406,zoneID=10534}},coords={x=0.69,y=0.406,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Polemarch Adrestes"},
[61129] = {id=61129,name="RSVP: Droman Aliothe",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="I serve my Queen and abide by my oath to guard this hollow and tend the spirits it encloses. Once, I might have enjoyed your Prince's party, but I am no longer suited to revelry. My world was destroyed long ago, and perhaps I have lost the joy I felt as its wild guardian. I would dearly like a reminder of my old home. I have heard those strange traders, the brokers, have unusual objects from other worlds. Perhaps they have something from mine?",objectivesText="Investigate the offers of the Brokers to see whether a remnant of Aliothe's world may be found. Progress: Have you found a reminder of my home for me?",starts={{npcID=160894,x=0.6,y=0.538,zoneID=11510}},ends={{npcID=160894,x=0.6,y=0.538,zoneID=11510}},coords={x=0.6,y=0.538,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Droman Aliothe"},
[61130] = {id=61130,name="RSVP: Sika",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Hello, ! Sika like to help. So much to do. Would go to Ember Court, but too many things only Sika can do. Very sorry.",objectivesText="Find others in Olympic Village to take on Sika 's tasks so she can attend the Ember Court. Progress: Busy, busy. Too busy. No one else can do all the things.",starts={{npcID=166577,x=0.526,y=0.826,zoneID=10534}},ends={{npcID=166577,x=0.526,y=0.826,zoneID=10534}},coords={x=0.526,y=0.826,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Sika"},
[61139] = {id=61139,name="RSVP: Choofa",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Oooh a party! I love parties. My friends have to come too or it's just not as much fun. Ask them please! You need to find Awool, Rury, and Slanknen so we can go together.",objectivesText="Make sure all of Choofa 's friends are able to attend the party. Progress: Friends all ready?",starts={{npcID=160814,x=0.636,y=0.366,zoneID=11510}},ends={{npcID=160814,x=0.636,y=0.366,zoneID=11510}},coords={x=0.636,y=0.366,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Choofa"},
[61141] = {id=61141,name="Deathfang's Favorite Toy",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=12876,mapID=1536,objectivesText="Throwin' Skull found Play with Deathfang",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=166274,text="Throwin' Skull found"},{orderIndex=1,type=0,amount=5,objectID=171591,text="Play with Deathfang"}},worldTaskTitle="Deathfang's Favorite Toy",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61148] = {id=61148,name="AHHH! Real Monsters!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="Enter a Rift Exit the Rift",questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=171514,text="Enter a Rift"},{orderIndex=3,type=0,amount=1,objectID=171829,text="Exit the Rift"}},worldTaskTitle="AHHH! Real Monsters!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61173] = {id=61173,name="RSVP: Mikanikos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Ember Court sounds interesting ... but very busy right now! Forsworn got into my supplies. Now everything jumbled and disorganized. Can't work in these conditions. My workshop isn't right! Help me! Get parts. Most will be damaged and you don't know how to tell about flaws. Bring me many to examine. I will find perfect part.",objectivesText="Assist Mikanikos by gathering potentially perfect parts so he can finish his construction and attend the Ember Court. Progress: Have my parts?",starts={{npcID=171647,x=0.502,y=0.212,zoneID=10534}},ends={{npcID=171647,x=0.502,y=0.212,zoneID=10534}},coords={x=0.502,y=0.212,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Mikanikos"},
[61174] = {id=61174,name="RSVP: Baroness Vashj",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I am no stranger to courts, Maw Walker. Having attended on Queen Azshara herself, and then later serving my Lord Illidan. That does not mean, however, that I accept every invitation I receive. Baroness Vashj smirks.> Impress me with your strength, $p, and I will believe Prince Renathal has power that is worth my time.",objectivesText="Gather the heads of fearsome foes to present to Baroness Vashj . Progress: Where are the heads of your enemies?",starts={{npcID=162487,x=0.676,y=0.46,zoneID=11462}},ends={{npcID=162487,x=0.676,y=0.46,zoneID=11462}},coords={x=0.676,y=0.46,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Baroness Vashj"},
[61189] = {id=61189,name="Further Gelatinous Research",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Accumulator Acquired Slime gathered",questType="world",db2Objectives={{orderIndex=1,type=0,amount=30,objectID=171746,text="Slime gathered"},{orderIndex=0,type=0,amount=1,objectID=171747,text="Accumulator Acquired"}},worldTaskTitle="Further Gelatinous Research",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61220] = {id=61220,name="AHHH! Real Monsters!",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="Assist Aspirant Thetes Repel the Devourer threat Helpless Aspirant rescued",questType="world",db2Objectives={{orderIndex=1,type=15,amount=1,objectID=0,text="Repel the Devourer threat"},{orderIndex=0,type=0,amount=1,objectID=171834,text="Assist Aspirant Thetes"},{orderIndex=6,type=0,amount=40,objectID=162685,text="Helpless Aspirant rescued"}},worldTaskTitle="AHHH! Real Monsters!",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61255] = {id=61255,name="RSVP: Alexandros Mograine",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. But before I leave my post, I must ensure my comrades will be safe while I am away. Fight your way into the Ossein Foundry and retrieve weapons from our rivals there. I will have them distributed among the troops while I make ready to depart.",objectivesText="Collect 9 Ossein Staves and 3 Ossein Battleaxes from the Ossein Foundry. Progress: Have you gotten the weapons yet?",starts={{npcID=171933,x=0.504,y=0.674,zoneID=11462}},ends={{npcID=171933,x=0.504,y=0.674,zoneID=11462}},coords={x=0.504,y=0.674,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="RSVP: Alexandros Mograine"},
[61256] = {id=61256,name="RSVP: Kleia and Pelagos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Oh, how wonderful! Thank you for the invitation to the Ember Court. We were just going to go cleanse ourselves with a meditation. That will be even more necessary if we are to travel soon. Care to join us?",objectivesText="Join Kleia and Pelagos in the Meditation chamber and face the memories of your past. Progress: Have you completed your meditation yet?",starts={{npcID=174916,x=0.558,y=0.864,zoneID=10534}},ends={{npcID=171951,x=0.578,y=0.856,zoneID=10534}},coords={x=0.558,y=0.864,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="RSVP: Kleia and Pelagos"},
[61303] = {id=61303,name="It's Raining Sparkles",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Speak to Lady Moonberry Mustering Enemies slain",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=171946,text="Speak to Lady Moonberry"},{orderIndex=1,type=0,amount=100,objectID=171948,text="Mustering Enemies slain"}},worldTaskTitle="It's Raining Sparkles",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61335] = {id=61335,name="Rage Against the Cage",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="You're looking for a mechanic, are you? Look no further! I've been toiling on a new necropolis for ages. When Nurakkir collapsed, we saw a golden opportunity! We came to salvage parts from the wreckage, but these brutes locked me up when I criticized their methods. But now you need help, right? I'm your construct! You get me out of here, and you've got yourself a new mechanic!",objectivesText="Free Ansid the Mechanic from his cage using Toc's key . Progress: Got a way to free me?",starts={{npcID=159814,x=0.486,y=0.186,zoneID=11462}},ends={{npcID=159814,x=0.486,y=0.186,zoneID=11462}},coords={x=0.486,y=0.186,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Rage Against the Cage"},
[61337] = {id=61337,name="March of the Eternal Protector",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="Defend Heraclor Assist Heraclor",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Defend Heraclor"},{orderIndex=7,type=0,amount=200,objectID=172025,text="Assist Heraclor"}},worldTaskTitle="March of the Eternal Protector",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61342] = {id=61342,name="Battles Won Long Ago",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Burning Thicket enemies killed Plant Banner at the Burning Thicket",questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=166380,text="Plant Banner at the Burning Thicket"},{orderIndex=0,type=0,amount=15,objectID=166501,text="Burning Thicket enemies killed"}},worldTaskTitle="Battles Won Long Ago",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61343] = {id=61343,name="Battles Won Long Ago",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Sepulcher of Knowledge enemies killed Plant Banner at the Sepulcher of Knowledge",questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=166381,text="Plant Banner at the Sepulcher of Knowledge"},{orderIndex=0,type=0,amount=15,objectID=166502,text="Sepulcher of Knowledge enemies killed"}},worldTaskTitle="Battles Won Long Ago",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61352] = {id=61352,name="All Will Be Consumed",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Devourer slain Collectors rescued",questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=163434,text="Devourer slain"},{orderIndex=2,type=0,amount=6,objectID=175808,text="Collectors rescued"}},worldTaskTitle="All Will Be Consumed",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61353] = {id=61353,name="All Will Be Consumed",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11462,mapID=1536,objectivesText="Devourer Invasion stopped Rift closed",questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Devourer Invasion stopped"},{orderIndex=2,type=0,amount=20,objectID=172068,text="Rift closed"}},worldTaskTitle="All Will Be Consumed",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61354] = {id=61354,name="RSVP: Lady Moonberry",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="Of course I will attend, , the Ember Court sounds like a lot of fun! But I cannot go without a gift! Hospitality gifts are an important tradition on many worlds and I feel obliged to provide something suitable for my host and fellow guests. Lady Moonberry suppresses a smirk.> Now for reasons that I'm suuuure won't interest you, I'll need a stout but pretty vine, some dangerous but beautiful blossoms, and of course some gorm pheromones. Easy enough for someone of your prowess.",objectivesText="Collect 3 Silverheart Vine Leaves , 9 Blooming Lasher Spurs , and a Gorm Pheromone Gland . Progress: Have you found all of the components for my gift?",starts={{npcID=172098,x=0.49,y=0.51,zoneID=11510}},ends={{npcID=172098,x=0.49,y=0.51,zoneID=11510}},coords={x=0.49,y=0.51,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="RSVP: Lady Moonberry"},
[61394] = {id=61394,name="Gormling Toss: Tranquil Pools",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Gormling in a Bag acquired Wayward Gormlings knocked down and bagged",questType="world",db2Objectives={{orderIndex=1,type=0,amount=8,objectID=168254,text="Wayward Gormlings knocked down and bagged"},{orderIndex=0,type=0,amount=1,objectID=172175,text="Gormling in a Bag acquired"}},worldTaskTitle="Gormling Toss: Tranquil Pools",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[61398] = {id=61398,name="Ember Court: Traditional",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1525,description="Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court. Venthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity. Our resources are stretched thin, . We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom . There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.",objectivesText="Collect 50 Candle Wax and 20 Death Blossoms . Death Blossoms can be harvested with the herbalism skill. Progress: Have you managed to gather the raw materials for our artisans yet?",starts={{npcID=156822,x=0.614,y=0.638,zoneID=10413}},ends={{npcID=156822,x=0.614,y=0.638,zoneID=10413}},coords={x=0.614,y=0.638,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Traditional"},
[61399] = {id=61399,name="Ember Court: Mortal Reminders",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=2717,mapID=1670,description="For a reasonable renumeration, Ta Cartel can supply the decorations you require. Restocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer. Your world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.",objectivesText="Help Keeper Ta'saran replenish stock by retrieving the items on the list he's provided you. Progress: Have you found something that fits each item on the list?",starts={{x=0.592,y=0.751,mapID=1670,npcID=156791}},ends={{x=0.592,y=0.751,mapID=1670,npcID=156791}},coords={mapID=1670,x=0.592,y=0.751},questType="world",worldTaskTitle="Ember Court: Mortal Reminders"},
[61400] = {id=61400,name="Ember Court: Mystery Mirrors",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="I support Prince Renathal's efforts and will certainly help the Ember Court! Mystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time. You will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.",objectivesText="Collect 12 Shrouded Mirror Shards , 12 Scorched Mirror Fragments , and 3 Molten Cores. Progress: Have you found the mirror fragments and an Ashen Core ?",starts={{npcID=172986,x=0.246,y=0.504,zoneID=10413}},ends={{npcID=172986,x=0.246,y=0.504,zoneID=10413}},coords={x=0.246,y=0.504,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Mystery Mirrors"},
[61401] = {id=61401,name="Ember Court: Venthyr Volunteers",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Oh, hello again! Did you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits. I need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.",objectivesText="Place 6 Recruiting Posters and test 3 Sinfall Recruits. Progress: Those posters need to be put in visible locations and the recruits need to be tested.",starts={{npcID=172614,x=0.61,y=0.394,zoneID=10413}},ends={{npcID=172614,x=0.61,y=0.394,zoneID=10413}},coords={x=0.61,y=0.394,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Venthyr Volunteers"},
[61402] = {id=61402,name="Ember Court: Stoneborn Reserves",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them. We will also need weapons for them. Sort that out and I will make sure the Prince and his guests are well protected.",objectivesText="Fill the anima canister by defeating enemy stoneborn in Dominance Keep. Collect 12 Stoneborn Glaives . Progress: Have you filled the anima canister and found enough weapons to equip our new comrades?",starts={{npcID=172502,x=0.264,y=0.292,zoneID=10413}},ends={{npcID=172502,x=0.264,y=0.292,zoneID=10413}},coords={x=0.264,y=0.292,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Stoneborn Reserves",db2QuestInfoID=1,db2QuestInfoName="Group"},
[61403] = {id=61403,name="Ember Court: Maldraxxus Army",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=8501,mapID=1536,description="So your prince's little parties have attracted unwanted attention? Emeni laughs.> I have my own long list of enemies, and far too many of them hide from me in the land of the living. Cowards! But I have finally found a solution. Take this crystal to my remains on Azeroth, and use it to project my image among the living for a short time so that I may exact revenge on my old kin.",objectivesText="Release Emeni 's projection in Vol'dun and help her defeat her ancient sethrak enemies. Progress: What are you waiting for? Those sethrak won't impale themselves.",starts={{npcID=172964,x=0.542,y=0.692,zoneID=11462}},ends={{npcID=172964,x=0.542,y=0.692,zoneID=11462}},coords={x=0.542,y=0.692,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Ember Court: Maldraxxus Army"},
[61404] = {id=61404,name="Ember Court: Tubbins's Tea Party",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1525,description="Theotar need tea for party? Tubbins make best! Special tea. Very special. Only I can make. Recipe need very good water from garden place. Good pool on special floaty island! You go get and Tubbins makes tea!",objectivesText="Collect Pristine Water from Ardenweald's Distant Grotto. Progress: Need special water to make special tea. Makes sense.",starts={{npcID=167863,x=0.31,y=0.576,zoneID=10413},{npcID=173299,x=0.312,y=0.574,zoneID=10413}},ends={{npcID=167863,x=0.31,y=0.576,zoneID=10413},{npcID=173299,x=0.312,y=0.574,zoneID=10413}},coords={x=0.31,y=0.576,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Tubbins's Tea Party",db2QuestInfoID=1,db2QuestInfoName="Group"},
[61405] = {id=61405,name="Ember Court: Divine Desserts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1533,description="Recipes very important. Must not be lost! I learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn. I bring desserts to Ember Court. Fair, yes?",objectivesText="Collect a sample of Banana Beef Pudding , 30 Aethereal Meat , and 20 Phantasmal Haunch . Then taste-test Stewart 's concoction. Progress: You ready to give ingredients and taste test?",starts={{npcID=172448,x=0.34,y=0.666,zoneID=10534}},ends={{npcID=172448,x=0.34,y=0.666,zoneID=10534}},coords={x=0.34,y=0.666,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Ember Court: Divine Desserts"},
[61406] = {id=61406,name="Ember Court: Mushroom Surprise!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court! Hmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me. Let's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps . You'll need to grapple your way up there.",objectivesText="Collect 18 Feather Caps , 24 Lacy Bell Morels , and 4 Violet Frills . Progress: Have you filled the foraging bag?",starts={{npcID=168429,x=0.402,y=0.412,zoneID=11462}},ends={{npcID=168429,x=0.402,y=0.412,zoneID=11462}},coords={x=0.402,y=0.412,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Ember Court: Mushroom Surprise!"},
[61407] = {id=61407,name="Ember Court: Atoning Rituals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement. However, I must ask for your assistance preparing the necessary components quickly. Capture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose. Sinstone fragments will also help us identify the sins of these lost souls.",objectivesText="Collect 125 Sinstone Fragments and deliver 2 Fugitive Souls to Avowed Ritualists. Progress: Fugitive souls can be found hiding in the darkest corners of the Halls of Atonement.",starts={{npcID=167332,x=0.718,y=0.404,zoneID=10413}},ends={{npcID=167332,x=0.718,y=0.404,zoneID=10413}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Atoning Rituals"},
[61408] = {id=61408,name="Ember Court: Glimpse of the Wilds",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11510,mapID=1565,description="It would be wonderful to show Revendreth the wild creatures of Ardenweald! You can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. Here's a net to use to subdue the Territorial Waders. They should follow you once you've caught them. Highland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly. We will get others to help too. This sounds like fun.",objectivesText="Bring 3 Highland Runestags, 8 Radiant Groupers and 4 subdued Territorial Waders to Niya . Progress: We need Radiant Groupers, Highland Runestags, and Territorial Waders please.",starts={{npcID=172352,x=0.562,y=0.556,zoneID=11510}},ends={{npcID=172352,x=0.562,y=0.556,zoneID=11510}},coords={x=0.562,y=0.556,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Ember Court: Glimpse of the Wilds"},
