[61509] = {id=61509,name="Shinies of Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Chordy is bored, boooored! You want to go look for luckydos? Go on adventure with Chordy ? We go to land of wing people, go look for valuable luckydos there. Ready?",objectivesText="Use Chordy to locate and collect 10 valuable salvage around Bastion. Progress: Did we find anything good?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Shinies of Bastion"},
[61510] = {id=61510,name="A Bountiful Haul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Chordy want to go on adventure! You want to go too, yes? I scavenge, weapons, armor, and valuable luckydos! Though, luckydos seem to be in short supply these days. We go to land of tree people! If we search together, we'll find many luckydos!",objectivesText="Use Chordy to locate and collect 10 valuable salvage in Ardenweald. Progress: Did we find anything good?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="A Bountiful Haul"},
[61511] = {id=61511,name="Things They Leave Behind",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Chordy bored. Chordy want to go on adventure! You want to go too, yes? Pale people in tall buildings have many shinies and luckydos. We go there and find some for ourselves! You ready to go?",objectivesText="Use Chordy to locate and collect 10 valuable salvage in Revendreth. Progress: Did we find anything good?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=161270,x=0.55,y=0.686,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Things They Leave Behind"},
