[61522] = {id=61522,name="Corpse Run",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1536,description="There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?",objectivesText="Return the Bone Carcass to Rathan at Butcher Block. Progress: Yes? Did you find anything on your supply run?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=158300,x=0.542,y=0.68,zoneID=11462},{npcID=158300,x=0.332,y=0.546,zoneID=11400}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Corpse Run"},
