[61738] = {id=61738,name="Ember Court: Lost Chalice Band",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="Hips was smart to send you my way. The Lost Chalice Band plays the best music this side of the Maw! The band is not quite ready to tour yet, however. The musicians are all safe in the crypt behind me, but their instruments have been confiscated by our obnoxious neighborhood authorities! Noise complaints and all that. Help me get those back, and perhaps recruit a few groupies and roadies along the way to help out, and we shall throw the best concert your court has ever seen!",objectivesText="Use band posters to recruit 10 groupies and 10 roadies and recover 3 Confiscated Band Supplies. Progress: Any venthyr or dredger will do. We are not picky about our fans.",starts={{npcID=173173,x=0.55,y=0.438,zoneID=10413}},ends={{npcID=173173,x=0.55,y=0.438,zoneID=10413}},coords={x=0.55,y=0.438,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Ember Court: Lost Chalice Band"},
