[61880] = {id=61880,name="Honored Attendance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="It is my humble honor to be the Ember Court's first guest. Please inform Prince Renathal and all of your other compatriots that I will certainly attend whenever you wish to open the gates.",objectivesText="Inform Temel that Cryptkeeper Kassir will attend the Ember Court.",starts={{npcID=163073,x=0.702,y=0.562,zoneID=10413}},ends={{npcID=164966,x=0.28,y=0.43,zoneID=10413}},coords={x=0.702,y=0.562,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Honored Attendance"},
[61882] = {id=61882,name="Formal Entertainment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1525,description="The Accuser will be pleased that you have chosen such humble and formal entertainment for the first Ember Court. I look forward to the occasion.",objectivesText="Inform Temel that you have secured entertainment for the Ember Court.",starts={{npcID=167332,x=0.718,y=0.404,zoneID=10413}},ends={{npcID=164966,x=0.28,y=0.43,zoneID=10413}},coords={x=0.718,y=0.404,source="quest_giver",zoneID=10413},questType="world",worldTaskTitle="Formal Entertainment"},
