[61996] = {id=61996,name="Say The Magic Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Ever since I cast my first spell, I've not been able to get enough of magic! It's not as hard as all those liches say it is. You focus your thoughts, say the words, and magic starts happening! There are tomes documenting ancient spells stored in the Archivam of Revendreth. Help me gather them so I can learn some new spells!",objectivesText="Help Sabrina learn 12 new spells in Revendreth.",starts={{npcID=159226,x=0.548,y=0.688,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.548,y=0.688,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Say The Magic Words"},
[62051] = {id=62051,name="Gormling Toss: Spirit Glen",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11510,mapID=1565,objectivesText="Gormling in a Bag acquired Wayward Gormlings knocked down and bagged",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=173520,text="Gormling in a Bag acquired"},{orderIndex=1,type=0,amount=8,objectID=173521,text="Wayward Gormlings knocked down and bagged"}},worldTaskTitle="Gormling Toss: Spirit Glen",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
