[62194] = {id=62194,name="Fighting Words",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10534,mapID=1536,description="Throughout the Shadowlands, there is so much magic to learn! A threat in Bastion has put many of their ancient teachings in danger. I wish to study their scrolls before they are lost forever. We must travel there and safeguard what we can! Help me fight back the Forsworn at the Temple of Humility and save the scrolls within.",objectivesText="Help Sabrina collect 8 Ancient Teachings and eliminate 8 Forsworn enemies.",starts={{npcID=159226,x=0.548,y=0.688,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.548,y=0.688,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Fighting Words"},
[62195] = {id=62195,name="The Last Word",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10413,mapID=1536,description="Inquisitor Darksion was an aspiring practitioner of the arcane arts before Denathrius locked her away. I've heard she will share her knowledge with anyone that releases her from imprisonment. I want to learn all she knows! We must free her!",objectivesText="Help Sabrina free Inquisitor Darksion. Progress: Did we find anything good?",starts={{npcID=158259,x=0.504,y=0.474,zoneID=11462},{npcID=159226,x=0.548,y=0.688,zoneID=11462}},ends={{npcID=167150,x=0.55,y=0.686,zoneID=11462}},coords={x=0.504,y=0.474,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="The Last Word"},
