[62214] = {id=62214,name="Forces of Perdition",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Survival requires that we keep our enemies in check, Maw Walker. With Gorgoa overflowing, the Mawsworn continue to gain strength. Perdition Hold has been fortified with fresh troops. We cannot allow the Mawsworn to bolster their ranks any further. Make your way into Perdition Hold and decimate their forces. When the work is done, you may return to me for your reward.",starts={{npcID=162804,x=0.468,y=0.416,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.468,y=0.416,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Forces of Perdition",db2QuestInfoID=1,db2QuestInfoName="Group"},
[62235] = {id=62235,name="Allay Their Fears",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="Korinna's Allaying Crook Allaying Crook charged Wildlife absorbed Allaying Ritual completed",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=175556,text="Korinna's Allaying Crook"},{orderIndex=1,type=0,amount=1,objectID=173763,text="Allaying Crook charged"},{orderIndex=2,type=0,amount=20,objectID=173762,text="Wildlife absorbed"},{orderIndex=4,type=0,amount=1,objectID=173773,text="Allaying Ritual completed"}},worldTaskTitle="Allay Their Fears",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62239] = {id=62239,name="Rodent Removal",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="<The weapon buzzes with a dark, static energy. Whatever this Mawsworn was testing, it appears to have been somewhat successful on the nearby rodents. Further investigation may yield additional information.>",objectivesText="Test the Tormentor's Rod on 8 Giant Mawrats in The Beastwarrens.",starts={{npcID=365084,x=0.603,y=0.721,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.603,y=0.721,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Rodent Removal"},
