[62362] = {id=62362,name="Volatile Reactions",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The living slime within Maldraxxus naturally produces a powerful catalyst used in many of the House of Eyes's poisons. There is always a need for the substance. It would be of great help if you could retrieve some for us.",objectivesText="Collect 15 animated catalysts from the slime around Maldraxxus . Progress: Worry not, despite its appearance the catalyst is not toxic on its own.",starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Volatile Reactions"},
[62363] = {id=62363,name="Heavy Lifting",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="The stronger members of the House of the Chosen tend to take a fairly specific form. No doubt you've seen the larger warriors in the house? They are the greatest threat in their collective force. Thin them out.",objectivesText="Kill 20 warriors of the House of the Chosen.",starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Heavy Lifting"},
[62364] = {id=62364,name="Dire Learning",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="Necromancers and liches often use powerful tomes to assist in their rituals. Now that the House of Rituals has expanded their reach, the tomes can be found anywhere where their members are active. Find these books and destroy them. It won't end their vile experiments but it should at least delay them.",objectivesText="Destroy 15 Tome of Rituals .",starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Dire Learning"},
[62390] = {id=62390,name="Body Count",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11462,mapID=1536,description="I am acquainted with a few fleshcrafters who work outside of the House of Constructs. If we can find reagents for them, they can supply our war effort with constructs. The House of Constructs has plenty of excess body parts. Find them and bring them back here.",objectivesText="Collect 30 abomination parts from around Maldraxxus . Progress: We'll take any quality of parts you can find.",starts={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},ends={{npcID=167603,x=0.512,y=0.168,zoneID=11462}},coords={x=0.512,y=0.168,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Body Count"},
[62451] = {id=62451,name="Assault on the Vestibule",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=10534,mapID=1533,objectivesText="Take the Colossal Core Charge the Colossal Core Charge the Colossal Core Insert the Colossal Core Push the Button",questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=174303,text="Take the Colossal Core"},{orderIndex=1,type=0,amount=1,objectID=174304,text="Charge the Colossal Core"},{orderIndex=2,type=15,amount=1,objectID=0,text="Charge the Colossal Core"},{orderIndex=9,type=0,amount=1,objectID=174305,text="Insert the Colossal Core"},{orderIndex=10,type=0,amount=1,objectID=174306,text="Push the Button"}},worldTaskTitle="Assault on the Vestibule",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[62691] = {id=62691,name="A Calling in Revendreth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=10986,mapID=1700,description="We got a lot of problems out there, boss. Big ones, little ones, really smelly ones, it's a lot. If we're gonna take on Denathrius, the first thing we gotta do is clean up right here in Revendreth. We get things cleaned up, yeah? Then we get some new allies, and we probably get our hands on some anima to boot. It's a call to action, it is. And it's important that we get started right away. Get on out there and get your boots muddy!",objectivesText="Complete 3 World Quests in Revendreth. Progress: What do ya want?",starts={{x=0.616,y=0.756,mapID=1700,npcID=165302}},ends={{x=0.616,y=0.756,mapID=1700,npcID=165302}},coords={mapID=1700,x=0.616,y=0.756},questType="world",worldTaskTitle="A Calling in Revendreth",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62692] = {id=62692,name="A Calling in Bastion",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11012,mapID=1707,description="Our forces are weakened by doubt and our temples are under assault. If we are to aid the rest of the Shadowlands, we must begin here, in Bastion. Travel the golden fields and root out evil wherever you may find it. In time, we will rebuild our forces and our anima stores, and stand tall once more. Today, you walk the path of courage--it is your calling. Show our people that doubt will not fester here.",objectivesText="Complete 3 World Quests in Bastion. Progress: Do the hills echo with the cries of your victories, Maw Walker?",starts={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},ends={{npcID=160387,x=0.41,y=0.412,zoneID=11012}},coords={x=0.41,y=0.412,source="quest_giver",zoneID=11012},questType="world",worldTaskTitle="A Calling in Bastion",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62693] = {id=62693,name="A Calling in Ardenweald",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12858,mapID=1701,description="Ardenweald is fractured, its roots strangled. Before we can begin to regrow our glades, we must unearth the evils that have festered here. We call to you, today, to defend our forests. Take the weald paths through our lands, aiding our allies and defeating our enemies. With these actions, we will renew our forces, and rebuild our anima. In time, hope will blossom. Our trust is in you, our newest seedling.",objectivesText="Complete 3 World Quests in Ardenweald. Progress: Have you brought hope and faith to our people today?",starts={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},ends={{npcID=167195,x=0.536,y=0.066,zoneID=12858},{npcID=167195,x=0.536,y=0.066,zoneID=12858}},coords={x=0.536,y=0.066,source="quest_giver",zoneID=12858},questType="world",worldTaskTitle="A Calling in Ardenweald",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
[62694] = {id=62694,name="A Calling in Maldraxxus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=12876,mapID=1698,description="Today marks the beginning of our path to victory. Enemies surround us on all sides. Aid our troops on the battlefield and return with the resources we need to wage our war. Once we have secured our home front, we can direct our efforts outwards. Such is your calling. Failure is unacceptable.",objectivesText="Complete 3 World Quests in Maldraxxus. Progress: How goes the battle?",starts={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},ends={{npcID=158339,x=0.478,y=0.292,zoneID=12876}},coords={x=0.478,y=0.292,source="quest_giver",zoneID=12876},questType="world",worldTaskTitle="A Calling in Maldraxxus",db2QuestInfoID=271,db2QuestInfoName="Calling Quest"},
