[62723] = {id=62723,name="Bolstering Bastion",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12916,mapID=1533,description="You are no aspirant, but I welcome any aid that Oribos might bring us in these dire times. Please, aid our people in any way you can. With anima in low supply and the insidious Forsworn encroaching from all sides, there is no shortage of trials to overcome. Do this for us, and I will see to it myself that our almighty Archon hears of your deeds in service of the kyrian. Mark well my words, and follow the path.",objectivesText="Aid Bastion by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Bastion dungeons.",starts={{npcID=163427,x=0.51,y=0.468,zoneID=10534},{npcID=168517,x=0.374,y=0.61,zoneID=11012}},ends={{npcID=163427,x=0.51,y=0.468,zoneID=10534},{npcID=168517,x=0.374,y=0.61,zoneID=11012}},coords={x=0.51,y=0.468,source="quest_giver",zoneID=10534},questType="world",worldTaskTitle="Bolstering Bastion"},
