[62748] = {id=62748,name="Rallying Maldraxxus",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13228,mapID=1536,description="We need all the help we can get! It's taking all we have to hold our ground against the other houses, let alone gain any ground against them. Truth be told, your blade will be welcome anywhere. There are no shortage of battles to be won, foes to be toppled, or weary soldiers to be relieved. Help us regain control of Maldraxxus , and in the name of the Primus I will see you are amply rewarded.",objectivesText="Aid Maldraxxus by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Maldraxxus dungeons.",starts={{npcID=175008,x=0.528,y=0.682,zoneID=11462}},ends={{npcID=175008,x=0.528,y=0.682,zoneID=11462}},coords={x=0.528,y=0.682,source="quest_giver",zoneID=11462},questType="world",worldTaskTitle="Rallying Maldraxxus"},
[62763] = {id=62763,name="Support the Court",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13334,mapID=1565,description="Groves are under attack everywhere! There simply aren't enough of us to protect them all! You just might be our only hope. We must restore order, or more precious souls will be lost to us. Please, help anyone you can, anywhere you can. My heart cannot bear to see any more pain! I'll make sure the Winter Queen hears of your deeds, don't you worry!",objectivesText="Defend Ardenweald by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Ardenweald dungeons.",starts={{npcID=172431,x=0.492,y=0.522,zoneID=11510},{npcID=172431,x=0.5,y=0.402,zoneID=12858},{npcID=172431,x=0.5,y=0.402,zoneID=12858}},ends={{npcID=172431,x=0.492,y=0.522,zoneID=11510},{npcID=161509,x=0.5,y=0.402,zoneID=12858},{npcID=172431,x=0.5,y=0.402,zoneID=12858},{npcID=161509,x=0.5,y=0.402,zoneID=12858},{npcID=172431,x=0.5,y=0.402,zoneID=12858}},coords={x=0.492,y=0.522,source="quest_giver",zoneID=11510},questType="world",worldTaskTitle="Support the Court"},
