[62778] = {id=62778,name="Reinforcing Revendreth",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=12831,mapID=1525,description="Denathrius must be stopped at all costs. However, we've no hope of taking him out while his forces still control much of Revendreth . If you are here to aid us, then there is no shortage of work to be done. Disposing of my father's many allies being chief among that work, of course, but any aid you can provide will be of use. There is too much at stake for all the Shadowlands if we fail. I will see to it that you are handsomely rewarded for your efforts.",objectivesText="Aid Revendreth by completing Side Quests, Bonus Objectives, World Quests, and slaying rare creatures. You may also defeat powerful foes in Revendreth dungeons.",starts={{npcID=158653,x=0.518,y=0.366,zoneID=10986},{npcID=175056,x=0.614,y=0.604,zoneID=10413}},ends={{npcID=158653,x=0.518,y=0.366,zoneID=10986},{npcID=175056,x=0.614,y=0.604,zoneID=10413}},coords={x=0.518,y=0.366,source="quest_giver",zoneID=10986},questType="world",worldTaskTitle="Reinforcing Revendreth"},
