[63031] = {id=63031,name="Acquisition: Crystallized Stygia",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari would likely be interested in any of these shards you come across.>",objectivesText="Collect 10 Crystallized Stygia and return it to Ve'nari in the Maw . Progress: What have you collected, <class>?",starts={{npcID=364899,x=0.212,y=0.341,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.212,y=0.341,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Crystallized Stygia"},
[63038] = {id=63038,name="Guaranteed Delivery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari . Clutched in their hand is a list of items and a containment orb . Finishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>",starts={{npcID=175797,x=0.306,y=0.584,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.306,y=0.584,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Guaranteed Delivery",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63039] = {id=63039,name="A Monument to Vengeance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="<Corpses of Ebon Blade knights litter the Crucible of the Damned, displaying the aftermath of your first foray into this desolate place. Their sacrifice should not be forgotten.>",objectivesText="Collect 8 Ebon Runeblades and build a monument to the Ebon Blade's sacrifice in the Crucible of the Damned. Progress: <This precipice is highly visible throughout the Maw . Building the monument here will surely draw the Jailer's ire.>",starts={{npcID=175807,x=0.222,y=0.478,zoneID=11400}},ends={{npcID=364911,x=0.234,y=0.499,zoneID=11400}},coords={x=0.222,y=0.478,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Monument to Vengeance"},
[63040] = {id=63040,name="Guaranteed Delivery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari . Clutched in their hand is a list of items and a containment orb . Finishing this broker's task and sending the items back to Ve'nari will surely earn you some compensation.>",starts={{npcID=175797,x=0.306,y=0.584,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.306,y=0.584,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Guaranteed Delivery",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63043] = {id=63043,name="Sundered Souls",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The traps... they didn't affect us before. Too many souls... escaping. They... made new traps... tear apart fleeing souls... ...too late for me. Destroy... so others might escape!",objectivesText="Destroy 10 Soulrend Traps in the Tremaculum.",starts={{npcID=175813,x=0.282,y=0.146,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400},{npcID=178228,x=0.27,y=0.138,zoneID=11400}},coords={x=0.282,y=0.146,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Sundered Souls"},
[63045] = {id=63045,name="Feed Your Soul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="They... drained my anima... to fuel their ritual... Souls of great power are brought here... to this altar... and sacrificed to conjure unspeakable horrors bound to the Jailer. I was powerful once... Imbue me with the anima they stole... and I can be powerful again. Then, together... we will destroy the one who leads their efforts.",starts={{npcID=175866,x=0.25,y=0.666,mapID=1543}},ends={{npcID=162804,x=0.468,y=0.416,mapID=1543}},coords={x=0.25,y=0.666,source="quest_giver",mapID=1543},questType="world",worldTaskTitle="Feed Your Soul",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63047] = {id=63047,name="Acquisition: Runeforged Shackles",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari could find some use in studying these runes.>",objectivesText="Collect 9 Runeforged Shackles and return them to Ve'nari in the Maw . Progress: Another transaction?",starts={{npcID=364926,x=0.257,y=0.242,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.257,y=0.242,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Runeforged Shackles"},
[63050] = {id=63050,name="Acquisition: Blazing Ingots",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari could aid her attempts at unlocking the Jailer's secrets.>",objectivesText="Collect 12 Blazing Ingots and return them to Ve'nari in the Maw . Progress: What's this?",starts={{npcID=364932,x=0.39,y=0.399,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.39,y=0.399,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Blazing Ingots"},
[63062] = {id=63062,name="Torment for the Taking",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="<A broker device has been abandoned here. It seems like it was being used to siphon energy from rifts of soul energy that have erupted in the area. The brokers surely would not have sought to harness this energy if it didn't have a use. Perhaps you should finish what they started.>",objectivesText="Fill the Phasic Siphoner from the Soul Fissures in Detrithos and return it to Ve'nari in the Maw .",starts={{npcID=364937,x=0.28,y=0.47,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.28,y=0.47,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Torment for the Taking"},
[63069] = {id=63069,name="What They Know",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari would likely be very interested in what he found. Unfortunately, his notes look to have been scattered far and wide by the local beasts.>",objectivesText="Collect 18 Torn Journal Pages in the Hungering Wastes and return them to Ve'nari in the Maw . Progress: That book... that is a pathfinder's journal you carry!",starts={{npcID=364987,x=0.464,y=0.622,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.464,y=0.622,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="What They Know"},
[63072] = {id=63072,name="Acquisition: Stygic Ore",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Ve'nari could certainly find use for some of this ore, if you can manage to mine it.>",objectivesText="Collect 15 pieces of Stygic Ore in Marrow's Coppice and return them to Ve'nari in the Maw . Progress: What do you carry, Maw Walker?",starts={{npcID=364994,x=0.472,y=0.826,zoneID=11400}},ends={{npcID=162804,x=0.468,y=0.416,zoneID=11400}},coords={x=0.472,y=0.826,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Acquisition: Stygic Ore"},
[63100] = {id=63100,name="Misery's Company",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="<The husk of this poor soul has been stripped of everything, down to near nonexistence. This suffering cannot continue. Save the others from their misery.>",objectivesText="Kill 10 Hopeless Vessels in Gorgoa: River of Souls.",starts={{npcID=176069,x=0.246,y=0.454,zoneID=11400}},ends={{mapID=1543,npcID=176069,x=0.247,y=0.455}},coords={x=0.246,y=0.454,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Misery's Company"},
[63166] = {id=63166,name="A Shadowed Fate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="The Mawsworn... torture and torment souls within Ruin's Cradle. I... barely escaped, but I'm afraid I won't last long. Their twisted rituals... breaking souls to serve as wretched shades. Spare them this fate!",objectivesText="Free 6 Tormented Souls in Ruin's Cradle by stomping out the Circles of Agony binding them.",starts={{npcID=176029,x=0.298,y=0.208,zoneID=11400}},ends={{npcID=176029,x=0.298,y=0.208,zoneID=11400}},coords={x=0.298,y=0.208,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="A Shadowed Fate"},
[63179] = {id=63179,name="Drowned and Torn Asunder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1543,description="Maw Walker! I am relieved to see you in this place. A dark sect of kyrian who have allied themselves with the Maw stole my brothers and sisters from their posts in Bastion. They turned us over to a foul sea witch, the likes of which I've never seen. This... Helya, I believe they called her... seems determined to break us so that we might also join her ranks. Please, if you can, save my brethren.",objectivesText="Free 8 Drowning Kyrian in Gorgoa, the River of Souls.",starts={{npcID=176144,x=0.388,y=0.236,zoneID=11400}},ends={{npcID=176144,x=0.388,y=0.236,zoneID=11400}},coords={x=0.388,y=0.236,source="quest_giver",zoneID=11400},questType="world",worldTaskTitle="Drowned and Torn Asunder"},
[63543] = {id=63543,name="Necrolord Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!",objectivesText="Complete 1 quests in Perdition Hold and the Face of Oblivion.",starts={{x=0.338,y=0.548,mapID=1543,npcID=177072}},ends={{x=0.338,y=0.548,mapID=1543,npcID=177072}},coords={mapID=1543,x=0.338,y=0.548},questType="world",db2Objectives={{orderIndex=1,type=14,amount=1,objectID=92362,text="Help Maldraxxi forces assault Perdition Hold"},{orderIndex=3,type=0,amount=1,objectID=177532,text="Advance to the Altar of Domination"},{orderIndex=0,type=0,amount=1,objectID=177674,text="Report to Draka at the gates of Perdition Hold"},{orderIndex=2,type=0,amount=1,objectID=177290,text="Use Draka's Battlehorn to signal the advance"}},worldTaskTitle="Necrolord Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
