[63775] = {id=63775,name="Cryptograms and Keys",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The repositories of knowledge within Korthia have layers of security--for very good reasons. Each vault requires cryptographs in order to decode and disable the barriers. They are, for lack of a better term, the keys to every secret. Search outside the Vault for cryptographs stolen by the Mawsworn and return them to me. I will keep them, and the secrets they protect, safe.",objectivesText="Retrieve 6 Stolen Cryptographs from outside the Vault and Seeker's Quorum. Progress: We cannot allow the Jailer to raid the Vaults of Korthia .",starts={{npcID=179082,x=0.64,y=0.23,zoneID=13570}},ends={{npcID=179082,x=0.64,y=0.23,zoneID=13570}},coords={x=0.64,y=0.23,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Cryptograms and Keys"},
[63776] = {id=63776,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Scholar's Den records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Be sure to check in the caverns below ground, as well! Bring those data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from the Scholar's Den. Progress: Have you retrieved the observational records from the Scholar's Den?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63777] = {id=63777,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in the Scholar's Den. Don't worry: they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",objectivesText="Retrieve 5 Sealed Containers from the Scholar's Den. Progress: Do you have the sealed containers ?",starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63778] = {id=63778,name="We Move Forward",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="It breaks my heart to see another land so utterly obliterated. I can imagine how beautiful Korthia must have been, once. But we must not wallow in what we've lost. Like Ara'lon taught me: we don't have to stand still. We can choose to fight. You can help by taking anima back from those Mawsworn. We can put it to use, building up our own forces and defenses.",starts={{npcID=178840,x=0.61,y=0.212,mapID=1961}},ends={{npcID=178840,x=0.61,y=0.212,mapID=1961}},coords={x=0.61,y=0.212,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="We Move Forward"},
[63779] = {id=63779,name="A Semblance of Normalcy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p, we have to help the attendants of Korthia . They have lost so much, so suddenly. Nearby, in the Sanctuary of Guidance, they would take offerings and leave them at shrines. Since the mawsworn invaded, they haven't been able to enter the Sanctuary or retrieve their precious offerings. If you could collect the offerings and retrieve them. It might allow the attendants some semblance of their normal lives.",starts={{npcID=179134,x=0.618,y=0.24,mapID=1961}},ends={{npcID=179134,x=0.618,y=0.24,mapID=1961}},coords={x=0.618,y=0.24,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="A Semblance of Normalcy"},
[63780] = {id=63780,name="See How THEY Like It!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Just thinking about how the Jailer's forces breached Ardenweald makes me so mad! And when I get mad, I get even. Or rather, I get your help with getting even! Slay those Mawsworn and bring back their emblems to show me how many you killed. I don't really care where you get them, as long as they come from those Maw jerks!",starts={{npcID=178838,x=0.612,y=0.212,mapID=1961}},ends={{npcID=178838,x=0.612,y=0.212,mapID=1961}},coords={x=0.612,y=0.212,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="See How THEY Like It!"},
[63781] = {id=63781,name="Mawsworn Battle Plans",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Which is more damaging to the enemy, destroying a contingent of their forces or interrupting their communications? Better yet, what if that communication allows you to best place your forces to ambush their reinforcements? I see you understand. There will be a Mawsworn lieutenant, Voxiferus, traveling from the Maw into Korthia , by way of the northern road. Find them, kill them, and bring me the battle plans.",starts={{npcID=178795,x=0.618,y=0.252,mapID=1961}},ends={{npcID=178795,x=0.618,y=0.252,mapID=1961}},coords={x=0.618,y=0.252,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Mawsworn Battle Plans"},
[63782] = {id=63782,name="Mawsworn Rituals",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The Mawsworn have a myriad of magic users among their forces. Their magic is unknown to us and that makes it deadly. We need to learn what they are capable of to properly prepare a defense. My own curiosity about their methods and rituals is secondary. Hunt down these vile casters and bring me their grimoires.",starts={{npcID=178799,x=0.616,y=0.234,mapID=1961}},ends={{npcID=178799,x=0.616,y=0.234,mapID=1961}},coords={x=0.616,y=0.234,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Mawsworn Rituals"},
[63783] = {id=63783,name="Anima Reclamation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. Nearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?",starts={{npcID=178793,x=0.618,y=0.256,mapID=1961}},ends={{npcID=178793,x=0.618,y=0.256,mapID=1961}},coords={x=0.618,y=0.256,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Anima Reclamation"},
[63784] = {id=63784,name="Gold's No Object",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p! How's things? We 'eard there was all kinds of interestin' stuff out 'ere. So, 'em sneakin' hoppers? Hard to see, innit? They've got 'emselves a shiny pelt as me 'n' the lads could use to stay out of sight, as it were. You know, avoid the bosses n' such. I need ya to capture a bundle of 'em. Gold's no object, just bring me the little pests alive.",starts={{npcID=179221,x=0.616,y=0.26,mapID=1961}},ends={{npcID=179221,x=0.616,y=0.26,mapID=1961}},coords={x=0.616,y=0.26,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Gold's No Object"},
[63785] = {id=63785,name="Continued Efforts: Seeker's Quorum",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The onslaught from Zovaal's forces continues to devastate these lands. We must send them a message. Show them we will not back down, . The might of Ardenweald stands with you.",starts={{npcID=178841,x=0.61,y=0.216,mapID=1961}},ends={{npcID=178841,x=0.61,y=0.216,mapID=1961}},coords={x=0.61,y=0.216,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Seeker's Quorum"},
[63786] = {id=63786,name="Sweep the Windswept Aerie",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The skies over Korthia are a dangerous place. Not only do the Mawsworn threaten our forces; the native creatures are also openly hostile. We must keep the skies safe for our own winged allies and beasts. The source of the native flyers is the Windswept Aerie. Go there and clear the aerie of aggressive creatures. Then, we shall have aerial supremacy.",starts={{npcID=178794,x=0.614,y=0.25,mapID=1961}},ends={{npcID=178794,x=0.614,y=0.25,mapID=1961}},coords={x=0.614,y=0.25,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Sweep the Windswept Aerie"},
[63787] = {id=63787,name="Continued Efforts: Mauler's Outlook",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="My Eyes tell me that the Mauler's Outlook is near the newly formed road from the Maw into Korthia . It would provide a strategic and tactical advantage. Unfortunately, the area is overrun with shardhides. If we can secure the area, it will provide us with a clear path to the west, as well as a point of observation to monitor the Jailer's forces.",starts={{npcID=179149,x=0.608,y=0.28,mapID=1961}},ends={{npcID=179149,x=0.608,y=0.28,mapID=1961}},coords={x=0.608,y=0.28,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Mauler's Outlook"},
[63788] = {id=63788,name="Continued Efforts: Sanctuary of Guidance",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The attendant's home has been destroyed by the Jailer, but we can help them in this trying time. Nearby is the Sanctuary of Guidance. They speak of it with reverence and great sadness. It is a place they go to pray and seek truth. It's currently infested with devourers. Clear out the devourers, so they may once more seek solace in their rituals and prayers.",starts={{npcID=178800,x=0.616,y=0.236,mapID=1961}},ends={{npcID=178800,x=0.616,y=0.236,mapID=1961}},coords={x=0.616,y=0.236,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Sanctuary of Guidance"},
[63789] = {id=63789,name="Continued Efforts: Scholar's Den",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="We cannot allow the mawsworn a foothold so close to our own encampment. The attendants say they keep this place hidden from eyes, but I will not rest easy while I can see them. Enter the Scholar's Den and cleanse the Jailer's forces from it.",starts={{npcID=178807,x=0.604,y=0.284,mapID=1961}},ends={{npcID=178807,x=0.604,y=0.284,mapID=1961}},coords={x=0.604,y=0.284,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Continued Efforts: Scholar's Den"},
[63790] = {id=63790,name="Broker's Bounty: Lord Azzorak",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A powerful dreadlord named Lord Azzorak is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Azzorak is a powerful foe. You may require several allies to slay him.",objectivesText="Defeat Lord Azzorak .",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Lord Azzorak",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63791] = {id=63791,name="Broker's Bounty: Valdinar the Curseborn",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A spike-armored Mawsworn named Valdinar the Curseborn is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Valdinar is a powerful foe. You may require several allies to defeat him.",objectivesText="Defeat Valdinar the Curseborn .",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Valdinar the Curseborn",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63792] = {id=63792,name="Broker's Bounty: Nocturnus the Unraveler",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A nefarious Maw magus named Nocturnus the Unraveler is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Nocturnus is a powerful foe. You may require several allies to defeat him.",objectivesText="Defeat Nocturnus the Unraveler . Progress: What news do you bring of Nocturnus the Unraveler ?",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Nocturnus the Unraveler",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63793] = {id=63793,name="Broker's Bounty: Ensydius the Defiler",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="A winged Mawsworn named Ensydius the Defiler is hampering the efforts of the Cartel in Korthia . Anyone who exterminates this evil will be rewarded. Use caution. Ensydius is a powerful foe. You may require several allies to defeat him.",objectivesText="Defeat Ensydius the Defiler .",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Ensydius the Defiler",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63794] = {id=63794,name="Broker's Bounty: Hungering Behemoth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="New lands bring new opportunity. We will provide a quantity of valuables to any interested party in return for a substantial amount of devourer blood , preferably the goliath kind. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.",objectivesText="Retrieve a Substantial Amount of Devourer Blood from a Hungering Behemoth. Progress: Have something to trade?",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Hungering Behemoth",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63822] = {id=63822,name="Venthyr Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13587,mapID=1543,objectivesText="Ask Burly Hurly to throw you Report to Prince Renathal on top of the Tremaculum wall Help Venthyr and Night Fae forces assault the Tremaculum Help Draven secure the upper platform Travel through a Maw Mirror Light directed into Maw Mirrors Mirror 1 Mirror 2 Mirror 3 Mirror 4 Gothra the Trembler slain",starts={{x=0.299,y=0.171,mapID=1543,npcID=178006}},ends={{x=0.299,y=0.171,mapID=1543,npcID=178006}},coords={mapID=1543,x=0.299,y=0.171},questType="world",db2Objectives={{orderIndex=1,type=0,amount=1,objectID=177926,text="Report to Prince Renathal on top of the Tremaculum wall"},{orderIndex=0,type=0,amount=1,objectID=178164,text="Ask Burly Hurly to throw you"},{orderIndex=2,type=14,amount=1,objectID=92340,text="Help Venthyr and Night Fae forces assault the Tremaculum"},{orderIndex=3,type=0,amount=1,objectID=178242,text="Help Draven secure the upper platform"},{orderIndex=4,type=0,amount=1,objectID=178243,text="Travel through a Maw Mirror"},{orderIndex=6,type=0,amount=1,objectID=178245,text="Mirror 1"},{orderIndex=7,type=0,amount=1,objectID=178246,text="Mirror 2"},{orderIndex=8,type=0,amount=1,objectID=178247,text="Mirror 3"},{orderIndex=9,type=0,amount=1,objectID=178248,text="Mirror 4"},{orderIndex=10,type=0,amount=1,objectID=178249,text="Gothra the Trembler slain"},{orderIndex=5,type=0,amount=4,objectID=178244,text="Light directed into Maw Mirrors"}},worldTaskTitle="Venthyr Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63823] = {id=63823,name="Night Fae Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! We need your help Maw Walker. Assist our forces on the battlefield!",objectivesText="Complete 1 quests in Perdition Hold and the Face of Oblivion.",starts={{x=0.224,y=0.433,mapID=1543,npcID=178828}},ends={{x=0.224,y=0.433,mapID=1543,npcID=178828}},coords={mapID=1543,x=0.224,y=0.433},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=178847,text="Report to Lord Herne"},{orderIndex=1,type=14,amount=1,objectID=92329,text="Help Night Fae forces assault Crucible of the Damned"},{orderIndex=2,type=0,amount=1,objectID=178848,text="Listen to Lord Herne's plan"},{orderIndex=3,type=0,amount=1,objectID=178872,text="Ask Lady Moonberry for help"},{orderIndex=7,type=0,amount=1,objectID=178947,text="Bonesmith Heirmir rescued"},{orderIndex=6,type=0,amount=1,objectID=178983,text="Lord Herne rescued"},{orderIndex=8,type=0,amount=1,objectID=178984,text="Margrave Sin'dane rescued"},{orderIndex=9,type=0,amount=1,objectID=178985,text="Thiernax rescued"},{orderIndex=4,type=0,amount=1,objectID=179118,text="Use Distracting Illusion to turn the guard away from you"},{orderIndex=5,type=0,amount=1,objectID=179119,text="Sneak past the distracted guard into the darkness"}},worldTaskTitle="Night Fae Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63824] = {id=63824,name="Kyrian Assault",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,description="The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!",objectivesText="Complete 1 quests in Perdition Hold and the Face of Oblivion.",starts={{x=0.428,y=0.448,mapID=1543,npcID=177900}},ends={{x=0.428,y=0.448,mapID=1543,npcID=177900}},coords={mapID=1543,x=0.428,y=0.448},questType="world",db2Objectives={{orderIndex=2,type=0,amount=1,objectID=178411,text="Fly with Xandria to attack Zovaal's Cauldron"},{orderIndex=3,type=15,amount=1,objectID=0,text="Summoning Ritual disrupted"},{orderIndex=9,type=0,amount=1,objectID=178460,text="Return to Cocyrus with Xandria"},{orderIndex=0,type=0,amount=1,objectID=177901,text="Report to Xandria in Cocyrus"},{orderIndex=1,type=14,amount=1,objectID=92351,text="Help Kyrian forces in Cocyrus and Zovaal's Cauldron"}},worldTaskTitle="Kyrian Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[63934] = {id=63934,name="Assail Mail",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, mortal! I am on a mission to deliver messages to our allies here in exciting Korthia . However, I was unable to complete my task. The messages I was programmed to transport were stolen by Mawsworn, and then incorrectly stored all over the ground. Would you collect the messages and return them to me? I will then see them delivered to their intended recipients. Thank you!",starts={{npcID=178802,x=0.614,y=0.224,mapID=1961}},ends={{npcID=178802,x=0.614,y=0.224,mapID=1961}},coords={x=0.614,y=0.224,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Assail Mail"},
[63935] = {id=63935,name="Precious Roots",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Korthia . A sister forest, stricken. But in the throes of destruction, there is still hope. Gather the anima, and build anew.",starts={{npcID=178842,x=0.61,y=0.214,mapID=1961}},ends={{npcID=178842,x=0.61,y=0.214,mapID=1961}},coords={x=0.61,y=0.214,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Precious Roots"},
[63936] = {id=63936,name="Devoured Anima",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Sika has idea! Devourers... devour. They eat anything! So they eat anima, too. If we take anima from devourers, then that anima is ours!",starts={{npcID=178797,x=0.616,y=0.238,mapID=1961}},ends={{npcID=178797,x=0.616,y=0.238,mapID=1961}},coords={x=0.616,y=0.238,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Devoured Anima"},
[63937] = {id=63937,name="Nasty, Big, Pointy Teeth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There's tons of interesting things to kill out here! Bears, birds, mawsworn, and gromits! Let's start with the gromits shall we? Go slaughter the fierce gromits in the Mauler's Outlook and bring me their FANGS! I can always use more teeth.",starts={{npcID=178805,x=0.6,y=0.274,mapID=1961}},ends={{npcID=178805,x=0.6,y=0.274,mapID=1961}},coords={x=0.6,y=0.274,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Nasty, Big, Pointy Teeth"},
[63949] = {id=63949,name="Shaping Fate",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=11400,mapID=1961,description="The Jailer's power and malevolence continue to grow. So must our resilience. Stand amongst your allies, . Push back against the darkness that would consume us all. Together, we will yet prevail. May the Purpose guide your hand.",objectivesText="Thwart the Jailer's efforts throughout Korthia and the Maw by completing Covenant Assaults, Daily Quests, looting treasures, slaying rare creatures, and defeating Tormentors of Torghast. Progress: One cannot run from history, but one's actions may shape the outcome.",starts={{npcID=177927,x=0.628,y=0.248,zoneID=13570}},ends={{npcID=177927,x=0.628,y=0.248,zoneID=13570}},coords={x=0.628,y=0.248,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Shaping Fate"},
[63950] = {id=63950,name="Razorwing Talons",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="These lands are not well known yet by my hunters, but we have discovered formidable beasts that reside here. Among these are the Razorwing: vicious predators with terrible talons... and the temper of a vorkai. Bring me some of their talons to help teach our newest hunters about the kinds of beasts they will face.",starts={{npcID=178837,x=0.614,y=0.212,mapID=1961}},ends={{npcID=178837,x=0.614,y=0.212,mapID=1961}},coords={x=0.614,y=0.212,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Razorwing Talons"},
[63954] = {id=63954,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in Seeker's Quorum. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",objectivesText="Retrieve 5 Sealed Containers from the Seeker's Quorum. Progress: Do you have the sealed containers ?",starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63955] = {id=63955,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup outside of the Vault. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",objectivesText="Retrieve 5 Sealed Containers from the Vault in Korthia . Progress: Do you have the sealed containers ?",starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63956] = {id=63956,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in the Windswept Aerie. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",objectivesText="Retrieve 5 Sealed Containers from the Windswept Aerie in Korthia . Progress: Do you have the sealed containers ?",starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63957] = {id=63957,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Seeker's Quorum records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring those data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from Seeker's Quorum in Korthia . Progress: Have you retrieved the observational records from Seeker's Quorum?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63958] = {id=63958,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from outside the Vault should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring that data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from outside the Vault in Korthia . Progress: Have you retrieved the observational records from the Vault?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63959] = {id=63959,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The Sanctuary of Guidance records should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring those data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from the Sanctuary of Guidance in Korthia . Progress: Have you retrieved the observational records from the Sanctuary of Guidance?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63960] = {id=63960,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. And don't forget to look below ground! Bring those data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia . Progress: Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63961] = {id=63961,name="Sealed Secrets",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in Mauler's Outlook. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.",objectivesText="Retrieve 5 Sealed Containers from Mauler's Outlook in Korthia . Progress: Do you have the sealed containers ?",starts={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},ends={{npcID=178845,x=0.646,y=0.254,zoneID=13570}},coords={x=0.646,y=0.254,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Sealed Secrets"},
[63962] = {id=63962,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records at Mauler's Outlook should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. Bring those data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from Mauler's Outlook in Korthia . Progress: Have you retrieved the observational records from Mauler's Outlook?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[63963] = {id=63963,name="Broker's Bounty: Ripmaul",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for a piece of heavily spiked hide from the beast known as Ripmaul. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.",objectivesText="Retrieve a Heavy Spiked Hide from Ripmaul. Progress: Have something to trade?",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Ripmaul",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63964] = {id=63964,name="Broker's Bounty: Grimtalon",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="New lands bring new opportunity. To any interested party, we will provide a quantity of valuables in return for an intact boney beak from the beast known as Grimtalon. Faint-hearted collectors need not bother. Please bring this sample to Ta'nasi in Keeper's Respite.",objectivesText="Retrieve a Mature Ossified Beak from Grimtalon. Progress: Have something to trade?",starts={{npcID=368772,x=0.647,y=0.255,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.647,y=0.255,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Broker's Bounty: Grimtalon",db2QuestInfoID=1,db2QuestInfoName="Group"},
[63965] = {id=63965,name="Razorwing Egg Rescue",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I'm amazed by the wildlife here in Korthia ! So many interesting creatures... Say, you know those flying beasts with the claws, the Razorwing? They sometimes knock their eggs out of their nests, and then they completely ignore them! If you find any abandoned eggs, could you bring them to me? Gently, of course. I wonder if they can be raised to be friendly? If not, well, it wouldn't be the first time I've had my antennae chewed on.",starts={{npcID=178839,x=0.614,y=0.214,mapID=1961}},ends={{npcID=178839,x=0.614,y=0.214,mapID=1961}},coords={x=0.614,y=0.214,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Razorwing Egg Rescue"},
[63989] = {id=63989,name="Oozing with Character",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! Can you take Plaguey with you and test their ability to infect organic life forms?",objectivesText="Help Plaguey test their infection ability in the Mauler's Outlook. Progress: They're good oozes, <name>.",starts={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},ends={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},coords={x=0.604,y=0.278,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Oozing with Character"},
[64015] = {id=64015,name="Into the Meat Grinder",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="All these mawsworn have got me excited for some slaughter! I've got a plan that probably won't end in you dying. Are you in?",objectivesText="Lay a trap for the Mawsworn.",starts={{npcID=178805,x=0.6,y=0.274,zoneID=13570}},ends={{npcID=178805,x=0.6,y=0.274,zoneID=13570}},coords={x=0.6,y=0.274,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Into the Meat Grinder"},
[64016] = {id=64016,name="Oozing with Character",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Ooz, I'd like to know if they are able to consume organic material and increase in size.",objectivesText="Help Ooz test their growth ability on Shardhide in the Mauler's Outlook. Progress: They're good oozes, <name>.",starts={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},ends={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},coords={x=0.604,y=0.278,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Oozing with Character"},
[64017] = {id=64017,name="Oozing with Character",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.",objectivesText="Help Bloop test their propagation ability in the Mauler's Outlook. Progress: They're good oozes, <name>.",starts={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},ends={{npcID=178806,x=0.604,y=0.278,zoneID=13570}},coords={x=0.604,y=0.278,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Oozing with Character"},
[64018] = {id=64018,name="The Weight of Stone",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The campaign continues, $p. The Stone Legion is here to turn the tide of battle. First, we must deliver supplies to our allies. The broken land of Korthia means we are the only ones who can keep our troops supplied. Second, we must deal with the mawsworn and the devourers. I have a very simple strategy. We are going to drop anima onto the mawsworn. That will attract the devourers to attack. Either they kill the mawsworn, or the mawsworn kills them. Regardless, we win.",objectivesText="Assist the Stone Legion in delivering supplies and anima.",starts={{npcID=178794,x=0.614,y=0.25,zoneID=13570}},ends={{npcID=178794,x=0.614,y=0.25,zoneID=13570}},coords={x=0.614,y=0.25,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="The Weight of Stone"},
[64040] = {id=64040,name="Once More, with Healing",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The mawsworn continue to engage our forces at the Vault. There are heavy casualties on both sides. We must help! Take this and restore any wounded covenant allies you find. Mikanikos helped me create it. It runs on anima and should help patch up anyone. Even the Stoneborn or Maldraxxi.",starts={{npcID=179194,x=0.616,y=0.24,mapID=1961}},ends={{npcID=179194,x=0.616,y=0.24,mapID=1961}},coords={x=0.616,y=0.24,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Once More, with Healing"},
[64043] = {id=64043,name="We Need a Healer - You!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You: take my device and get our wounded back on their feet!",starts={{npcID=179216,x=0.614,y=0.24,mapID=1961}},ends={{npcID=179216,x=0.614,y=0.24,mapID=1961}},coords={x=0.614,y=0.24,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="We Need a Healer - You!"},
[64065] = {id=64065,name="Local Reagents",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Korthia is an odd place. The wildlife here is different, likely due to years of exposure to the Vault and everything it contains. Are you ready to try some experiments? We'll need a good stock of reagents first. Near the Seeker's Quorum, you should be able to find shardhides, gromits, and razorwings. Watch out for their needles!",starts={{npcID=178806,x=0.604,y=0.278,mapID=1961}},ends={{npcID=178806,x=0.604,y=0.278,mapID=1961}},coords={x=0.604,y=0.278,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Local Reagents"},
[64070] = {id=64070,name="Staying Scrappy",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our army always need more weapons, armor, and troops. Always. We're getting reinforcements, but I can't keep everyone properly armed at this rate. Especially without a full forge and assistants. We'll have to make do with the next best thing. I need you to go get me any kind of scrap metal from the Mawsworn you can find. I'll figure out how to turn it into usable weapons.",starts={{npcID=179214,x=0.632,y=0.252,mapID=1961}},ends={{npcID=179214,x=0.632,y=0.252,mapID=1961}},coords={x=0.632,y=0.252,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Staying Scrappy"},
[64080] = {id=64080,name="Down to Earth",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I can hear the wings of the Mawsworn in the sky up above, taunting us. But a bird in the hand can be crushed. Take my spear and prove your aim. Pull a few down and smite them. Be sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point. I want to see you drag them out of the sky.",objectivesText="Use Korayn's Javelin to spear 4 Mawsworn Harbingers.",starts={{npcID=178841,x=0.61,y=0.216,zoneID=13570}},ends={{npcID=178841,x=0.61,y=0.216,zoneID=13570}},coords={x=0.61,y=0.216,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Down to Earth"},
[64089] = {id=64089,name="Teas and Tinctures",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="How delightful! What a lovely little spot of nature. Have you tried the local brews? Perhaps a nice herbal tea? No? Well, let's try it together! Search about this place and bring back any herbs that look... interesting. A good spot of tea, and then we shall get to work. I'll wait here.",starts={{npcID=179218,x=0.616,y=0.258,mapID=1961}},ends={{npcID=179218,x=0.616,y=0.258,mapID=1961}},coords={x=0.616,y=0.258,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Teas and Tinctures"},
[64101] = {id=64101,name="The Proper Procedures",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="I came here to observe the actions of those from Revendreth. However I have been met with news that concerns me. $p, the attendants tell me that they stored anima in canisters and that anima is being looted, by our own people. That's not how this should be done. Can I entrust you to retrieve the anima, so I might see it returned to its proper place?",starts={{npcID=178790,x=0.618,y=0.254,mapID=1961}},ends={{npcID=178790,x=0.618,y=0.254,mapID=1961}},coords={x=0.618,y=0.254,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="The Proper Procedures"},
[64103] = {id=64103,name="Old Tricks Work Best",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p. Here we are again, fighting alongside each other to protect the Shadowlands. We're waging a losing war, but we might be able to turn the tide. I need you to seek out some very specific commanders of the Mawsworn forces. In every army, there's good commanders and bad ones. By taking out the good ones, only the bad ones advance, weakening the force as a whole. Our Eyes have brought us the names. Now I just need you to kill them.",objectivesText="Kill Moros , Oizys , and Apate , commanders of the Mawsworn.",starts={{npcID=178808,x=0.606,y=0.28,zoneID=13570}},ends={{npcID=178808,x=0.606,y=0.28,zoneID=13570}},coords={x=0.606,y=0.28,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Old Tricks Work Best"},
[64104] = {id=64104,name="Think of the Critters",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat. I've saved some extra food that we can share with them. But I'm worried that they might be too shy to trust us, and I don't blame them! Here. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.",objectivesText="Approach and feed Hungry Gromits in Korthia .",starts={{npcID=178839,x=0.614,y=0.214,zoneID=13570}},ends={{npcID=178839,x=0.614,y=0.214,zoneID=13570}},coords={x=0.614,y=0.214,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Think of the Critters"},
[64129] = {id=64129,name="Charge of the Wild Hunt",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. I admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh . Aldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?",objectivesText="Mount Aldermeigh and slay Mawsworn in Korthia .",starts={{npcID=178840,x=0.61,y=0.212,zoneID=13570}},ends={{npcID=178840,x=0.61,y=0.212,zoneID=13570}},coords={x=0.61,y=0.212,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Charge of the Wild Hunt"},
[64166] = {id=64166,name="Random Memory Access",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too. Those people had lives, hopes, memories. I have to think that they can't all be gone, and we might be able to save something of them that lingers. Here, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. No one should be forgotten.",objectivesText="Collect Korthian Memories using the Ephemeral Wings .",starts={{npcID=179134,x=0.618,y=0.24,zoneID=13570}},ends={{npcID=179134,x=0.618,y=0.24,zoneID=13570}},coords={x=0.618,y=0.24,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Random Memory Access"},
[64194] = {id=64194,name="War Prototype",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="As Forgelite Prime, I always work to make something better! But largest centurions, they are much too large to bring to Korthia . This, I fix. Here is Atleos , field colossus prototype. Vanguard of the Kyrian! It needs testing. More testing. Must be perfect against a powerful opponent. Go, take Atleos and defeat a great Maw beast! Press all the buttons!",objectivesText="Use the Atleos prototype in the Windswept Aerie to defeat Kraxis . Progress: You have work still, yes?",starts={{npcID=179216,x=0.614,y=0.24,zoneID=13570}},ends={{npcID=179216,x=0.614,y=0.24,zoneID=13570}},coords={x=0.614,y=0.24,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="War Prototype"},
[64211] = {id=64211,name="Doorway in the Dark",level=60,requiredLevel=60,faction="alliance",expansion=8,zoneID=13570,mapID=1961,description="I fear our efforts to stop Zovaal have been thwarted, mortal. A doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago. I sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.",starts={{npcID=177194,x=0.628,y=0.262,mapID=1961}},ends={{npcID=180074,x=0.63,y=0.256,mapID=1961}},coords={x=0.628,y=0.262,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Doorway in the Dark"},
[64212] = {id=64212,name="Doorway in the Dark",level=60,requiredLevel=60,faction="horde",expansion=8,zoneID=13570,mapID=1961,description="I fear our efforts to stop Zovaal have been thwarted, mortal. A doorway has been opened to a forbidden realm... and the Banished One has reclaimed a power taken from him long ago. I sense your allies returning from the Sanctum of Domination. I must know every detail of what transpired.",starts={{npcID=177194,x=0.628,y=0.262,mapID=1961}},ends={{npcID=180073,x=0.606,y=0.278,mapID=1961}},coords={x=0.628,y=0.262,source="quest_giver",mapID=1961},questType="world",worldTaskTitle="Doorway in the Dark"},
[64240] = {id=64240,name="Flight of the Kyrian",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="We've engaged in a heavy battle at the entrance to the Vault of Secrets! Our forces could use some reinforcement. Please, guide my fellow Ascended to give support to our fighters there. The fighters on the ground can handle the clean-up, but they need shields and healing. Good luck!",objectivesText="Assist covenant forces from the air at the Vault of Secrets. Progress: Have you helped our forces at the Vault of Secrets?",starts={{npcID=179194,x=0.616,y=0.24,zoneID=13570}},ends={{npcID=179194,x=0.616,y=0.24,zoneID=13570}},coords={x=0.616,y=0.24,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Flight of the Kyrian"},
[64271] = {id=64271,name="A More Civilized Way",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Ah, $p. I have a matter to discuss with you. But not here. Meet me where the road enters Korthia from the Maw and I will explain.",objectivesText="Meet Nadjia near the road leading into Korthia .",starts={{npcID=178795,x=0.618,y=0.252,zoneID=13570}},ends={{npcID=178795,x=0.618,y=0.252,zoneID=13570}},coords={x=0.618,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="A More Civilized Way"},
[64273] = {id=64273,name="Containing the Helsworn",expansion=8,mapID=1543,questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Desmotaeron disrupted"},{orderIndex=1,type=0,amount=13,objectID=179866,text="T4"},{orderIndex=2,type=0,amount=25,objectID=179865,text="T3"},{orderIndex=3,type=0,amount=50,objectID=179864,text="T2"}},worldTaskTitle="Containing the Helsworn",db2QuestInfoID=136,db2QuestInfoName="Rare Elite World Quest"},
[64430] = {id=64430,name="Spill the Tea",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="It seems Tubbins and Gubbins have gone off somewhere. I do worry about the two of them. Be a dear and check on them. One never knows what shenanigans they might be up to. I last saw them speaking with one of the faeries from Ardenweald. They were discussing the fine art of tea making.",objectivesText="Find Tubbins and Gubbins.",starts={{npcID=179218,x=0.616,y=0.258,zoneID=13570}},ends={{npcID=179218,x=0.616,y=0.258,zoneID=13570}},coords={x=0.616,y=0.258,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Spill the Tea"},
[64432] = {id=64432,name="Strength to Weakness",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="$p, the scrap metal we've been recovering has some interesting properties. I have come to believe the mawsworn are imbuing their armor and increasing its durability. Take this lightning rod. First, you will need to get struck by lightning. Don't make that face. You'll be fine. But, you need to also be grounded on mawsworn metal. The large chains embedded in Korthia , near the Windswept Aerie should work. Once you are... ah... energized, I will send a tauralus, Borrhas, to carry you into battle.",objectivesText="Empower the lightning rod, then kill mawsworn.",starts={{npcID=179214,x=0.632,y=0.252,zoneID=13570}},ends={{npcID=179214,x=0.632,y=0.252,zoneID=13570}},coords={x=0.632,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Strength to Weakness"},
[64531] = {id=64531,name="Mor'geth",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=11400,mapID=1543,starts={{x=0.691,y=0.442,mapID=1543}},ends={{x=0.691,y=0.442,mapID=1543}},coords={mapID=1543,x=0.691,y=0.442},questType="world",worldTaskTitle="Mor'geth",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[64554] = {id=64554,name="Venthyr Assault",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1543,description="The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!",objectivesText="Complete 1 quests in Perdition Hold and the Face of Oblivion.",starts={{x=0.299,y=0.171,mapID=1543,npcID=178006}},ends={{x=0.299,y=0.171,mapID=1543,npcID=178006}},coords={mapID=1543,x=0.299,y=0.171},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=178164,text="Ask Burly Hurly to throw you"},{orderIndex=1,type=0,amount=1,objectID=177926,text="Report to Prince Renathal on top of the Tremaculum wall"},{orderIndex=2,type=0,amount=4,objectID=177524,text="Help Venthyr and Night Fae forces assault the Tremaculum"},{orderIndex=3,type=0,amount=1,objectID=178242,text="Help Draven secure the upper platform"},{orderIndex=4,type=0,amount=1,objectID=178243,text="Travel through a Maw Mirror"},{orderIndex=5,type=0,amount=4,objectID=178244,text="Light directed into Maw Mirrors"},{orderIndex=6,type=0,amount=1,objectID=178245,text="Mirror 1"},{orderIndex=7,type=0,amount=1,objectID=178246,text="Mirror 2"},{orderIndex=8,type=0,amount=1,objectID=178247,text="Mirror 3"},{orderIndex=9,type=0,amount=1,objectID=178248,text="Mirror 4"},{orderIndex=10,type=0,amount=1,objectID=178249,text="Gothra the Trembler slain"},{orderIndex=11,type=0,amount=1,objectID=180519,text="NEVER COMPLETE"}},worldTaskTitle="Venthyr Assault",db2QuestInfoID=268,db2QuestInfoName="Threat Wrapper"},
[64560] = {id=64560,name="Anima Reclamation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Our efforts here need a constant supply of troops, supplies, and anima. The last one is the hardest, for obvious reasons. But I've learned to be resourceful. Nearby there is a plentiful source of anima: the devourers that currently swarm the Sanctuary of Guidance. It's not as easy as beating it out of a soul, but it's just as effective, if you're strong enough. Are you?",objectivesText="Reclaim 8 Devoured Anima from devourers at the Sanctuary of Guidance. Progress: Every drop of anima we reclaim is a potential weapon against the Jailer.",starts={{npcID=178793,x=0.618,y=0.256,zoneID=13570}},ends={{npcID=178793,x=0.618,y=0.256,zoneID=13570}},coords={x=0.618,y=0.256,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Anima Reclamation"},
[64561] = {id=64561,name="Observational Records",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="Greetings, Maw Walker, a moment of your time? As you no doubt know, my cartel has quietly spread observational devices all across Korthia . But that data is no good to us if it is not retrieved. Which is where you come in. The records from the Windswept Aerie and Estuary of Awakening should be ready to collect. You won't see the devices themselves, but the data will appear to you as a bright orb. And don't forget to look below ground! Bring those data to me, and I will reward you handsomely.",objectivesText="Collect 5 Observational Records from the Windswept Aerie and Estuary of Awakening in Korthia . Progress: Have you retrieved the observational records from the Windswept Aerie and Estuary of Awakening?",starts={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},ends={{npcID=178844,x=0.648,y=0.252,zoneID=13570}},coords={x=0.648,y=0.252,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="Observational Records"},
[64562] = {id=64562,name="We Need a Healer - You!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13570,mapID=1961,description="There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You, take my device and get our wounded back on their feet!",objectivesText="Restore 10 Wounded Covenant Allies in Seeker's Quorum.",starts={{npcID=179216,x=0.614,y=0.24,zoneID=13570}},ends={{npcID=179216,x=0.614,y=0.24,zoneID=13570}},coords={x=0.614,y=0.24,source="quest_giver",zoneID=13570},questType="world",worldTaskTitle="We Need a Healer - You!"},
[64579] = {id=64579,name="Hollow Efforts",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. These empty metal husks still contain residual materials of creation that may be useful to us. Use my Forge-Tap near these metal spheres to harvest any Remnant Neomotes . You may also find other useful proto-materials!",objectivesText="Collect 40 Remnant Neomotes from Progenitor Forges using Firim's Forge-Tap . Progress: Have you gathered the materials already?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Hollow Efforts"},
[64592] = {id=64592,name="Historic Protection",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The outsiders have disrupted the sands. We cannot reach the terraforming records we need in order to collect necessary historical information. Will you assist us? Help Mai Obet collect historical records in the Endless Sands.",objectivesText="Help Mai Obet examine 6 Terraforming Records in the Endless Sands.",starts={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Historic Protection",db2QuestInfoID=1,db2QuestInfoName="Group"},
[64641] = {id=64641,name="Mysterious Greenery",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="There's a bright power emanating from the place above. I'm drawn towards it, like a moth to a light! I want to check it out, whatever it is. Won't you join me, please? It'll be so fun!",starts={{npcID=180799,x=0.552,y=0.644,mapID=1970}},ends={{npcID=179900,x=0.604,y=0.7,mapID=1970}},coords={x=0.552,y=0.644,source="quest_giver",mapID=1970},questType="world",worldTaskTitle="Mysterious Greenery"},
[64717] = {id=64717,name="Materials of Creation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. The spheres near the Forge of Afterlives contain trace amounts of materials unique to that location. I have modified my Forge-Tap to harvest those materials. Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges .",objectivesText="Collect 10 Eidolic Fragments and 300 Minor Enigmet . Progress: Have you collected what we need?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Materials of Creation"},
[64771] = {id=64771,name="Enlightened Exodus",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Hello, my friend! An expedition of Cartel Al was sent in search of this place long ago, and was believed lost. I entered Zereth Mortis in hopes of saving my splintered cartel from the dangers of the Maw that have preceded me. At last, I have found my old friend! And yet, she refuses to return to safety. Perhaps others can be convinced. Will you try?",starts={{npcID=181003,x=0.338,y=0.646,mapID=1970}},ends={{npcID=181003,x=0.338,y=0.646,mapID=1970}},coords={x=0.338,y=0.646,source="quest_giver",mapID=1970},questType="world",worldTaskTitle="Enlightened Exodus"},
[64785] = {id=64785,name="Overgrown Story",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose. There could be valuable research data to be obtained from these creatures. Use a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.",objectivesText="Gaiagantic and 12 Geomentals examined for research data. Progress: Have you completed the research?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Overgrown Story"},
[64850] = {id=64850,name="Traversing Torghast",level=50,requiredLevel=50,faction="both",expansion=8,zoneID=13575,mapID=1911,description="I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish . I am here to find great treasures within Torghast with the aid of my box. I can see you admiring it. Perhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead? I shall even reward you for anything you discover within.",objectivesText="Aid Ve'nish 's exploration of Torghast by completing a wing within Torghast. Use the wayfinder within Torghast to access different wings. Progress: How goes exploring the darkness of Torghast?",starts={{x=0.355,y=0.469,mapID=1911,npcID=181328}},ends={{x=0.355,y=0.469,mapID=1911,npcID=181328}},coords={mapID=1911,x=0.355,y=0.469},questType="world",worldTaskTitle="Traversing Torghast"},
[64854] = {id=64854,name="Trappings of Success",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The wildlife of Zereth Mortis are attracted to the frenetic creation energy that flows throughout the land. When the wildlife finds something charged with that energy... they eat it! The Mawsworn Cryptoseers have become aware of this and are attempting to find such wildlife to extract any remnants of that energy. Eliminate the Cryptoseers, and use the Containment Trap to subdue and examine the wildlife for our research.",objectivesText="Slay 5 Mawsworn Cryptoseers and examine the wildlife listed. Progress: You have collected data before the Cryptoseers?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Trappings of Success"},
[64960] = {id=64960,name="Feed the Annelids",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Hungry Annelid fed with Mawsworn",starts={{x=0.568,y=0.319,mapID=1970}},ends={{x=0.568,y=0.319,mapID=1970}},coords={mapID=1970,x=0.568,y=0.319},questType="world",db2Objectives={{orderIndex=2,type=0,amount=10,objectID=181703,text="Hungry Annelid fed with Mawsworn"}},worldTaskTitle="Feed the Annelids",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[64964] = {id=64964,name="Choose Your Fighter",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The presence of the Jailer's forces at Provis Strata have been causing untold damage to the region. If left unchecked, we will lose all knowledge in the area. One of our kin has prepared some automa to deal with the Mawsworn. Meet with them, and fight back against those who would disrespect Zereth Mortis in this manner.",objectivesText="Pick an automa construct and use it against the Mawsworn. Progress: Is the task complete?",starts={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},ends={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Choose Your Fighter"},
[64974] = {id=64974,name="Clean Up, Automa Aisle",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Plain of Actualization cleared",starts={{x=0.576,y=0.475,mapID=1970}},ends={{x=0.576,y=0.475,mapID=1970}},coords={mapID=1970,x=0.576,y=0.475},questType="world",db2Objectives={{orderIndex=0,type=15,amount=1,objectID=0,text="Plain of Actualization cleared"}},worldTaskTitle="Clean Up, Automa Aisle",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[64977] = {id=64977,name="Step Into the Ring",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13708,mapID=1970,description="One of the remarkable things we have found about these lands is that they seem to be adaptive and changing, even as ancient as they are. Things are not stationary. In the depths of the Nexus of Actualization there is a forge that appears made to test these various designs, and to learn. These creatures may one day be used to defend Zereth Mortis from threats, so you should test their effectiveness where possible. Go there, challenge what the forge creates and report back to me.",objectivesText="Defeat Generated creations in the Nexus of Actualization.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Step Into the Ring"},
[65072] = {id=65072,name="Not Safe for Work",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Rana's discovery of Progenitor relics at the Ageless Shards has created quite a stir among the Enlightened. These relics predate our earlier discoveries, and through them we may gain a deeper understanding of the workings of Zereth Mortis . Rana is collecting the relics, but I fear she is in danger. Agents of Cartel Xy have been spotted in the area, and will likely attempt to steal the relics. Please travel to the Ageless Shards, and help Rana collect the relics.",objectivesText="Assist Rana in her search and collect 8 Progenitor Relics . Progress: Have you collected the Progenitor Relics ?",starts={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},ends={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Not Safe for Work"},
[65081] = {id=65081,name="An Apple A Day",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Attack Crispin to dislodge apples",starts={{x=0.479,y=0.887,mapID=1970}},ends={{x=0.479,y=0.887,mapID=1970}},coords={mapID=1970,x=0.479,y=0.887},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182409,text="Attack Crispin to dislodge apples"}},worldTaskTitle="An Apple A Day",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65089] = {id=65089,name="Frog'it",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1970,objectivesText="Bounding Bufonid mounted Stolen Amocite Symbols recovered",starts={{x=0.6,y=0.688,mapID=1970}},ends={{x=0.6,y=0.688,mapID=1970}},coords={mapID=1970,x=0.6,y=0.688},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182444,text="Bounding Bufonid mounted"},{orderIndex=1,type=0,amount=30,objectID=181052,text="Stolen Amocite Symbols recovered"}},worldTaskTitle="Frog'it",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65096] = {id=65096,name="Your Death Or Mine",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We have obtained a wealth of information from relics discovered at the Ageless Shards. The Mawsworn are aware of our discoveries, and are trying to stop us. They have placed traps around the area to block access to the relics. We cannot allow the Jailer to cut off our access to those relics. Please eliminate this Mawsworn threat, and recover as many relics as possible.",objectivesText="Slay Punisher Makaris and collect 6 Sacred Relics . Progress: Have you secured the relics at the Ageless Shards?",starts={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},ends={{npcID=180630,x=0.614,y=0.514,zoneID=13536}},coords={x=0.614,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Your Death Or Mine"},
[65102] = {id=65102,name="Fish Eyes",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Use Fishing Portal to capture Souldrinker",starts={{x=0.478,y=0.64,mapID=1970}},ends={{x=0.478,y=0.64,mapID=1970}},coords={mapID=1970,x=0.478,y=0.64},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182701,text="Use Fishing Portal to capture Souldrinker"}},worldTaskTitle="Fish Eyes",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65115] = {id=65115,name="Researching the Solution",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Enigmatic Scrolls Warped Creatures slain",starts={{x=0.446,y=0.309,mapID=1970}},ends={{x=0.446,y=0.309,mapID=1970}},coords={mapID=1970,x=0.446,y=0.309},questType="world",db2Objectives={{orderIndex=0,type=1,amount=8,objectID=188118,text="Enigmatic Scrolls"},{orderIndex=1,type=0,amount=12,objectID=182710,text="Warped Creatures slain"}},worldTaskTitle="Researching the Solution",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65117] = {id=65117,name="Bad Samples",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Warped Anima Sample Injured Enlightened rescued Sample Container recovered",starts={{x=0.441,y=0.308,mapID=1970}},ends={{x=0.441,y=0.308,mapID=1970}},coords={mapID=1970,x=0.441,y=0.308},questType="world",db2Objectives={{orderIndex=1,type=0,amount=8,objectID=182719,text="Injured Enlightened rescued"},{orderIndex=0,type=1,amount=20,objectID=188121,text="Warped Anima Sample"},{orderIndex=2,type=0,amount=1,objectID=182774,text="Sample Container recovered"}},worldTaskTitle="Bad Samples",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65119] = {id=65119,name="Automa Ops",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Meet up with Rana Targeting Relic obtained Mawsworn forces destroyed Elite Value Eric's Area 1/1",starts={{x=0.568,y=0.327,mapID=1970}},ends={{x=0.568,y=0.327,mapID=1970}},coords={mapID=1970,x=0.568,y=0.327},questType="world",db2Objectives={{orderIndex=0,type=0,amount=1,objectID=182850,text="Meet up with Rana"},{orderIndex=1,type=1,amount=1,objectID=188137,text="Targeting Relic obtained"},{orderIndex=2,type=15,amount=1,objectID=0,text="Mawsworn forces destroyed"},{orderIndex=3,type=0,amount=17,objectID=182858,text="Elite Value"},{orderIndex=5,type=0,amount=40,objectID=181063,text="Eric's Area"},{orderIndex=6,type=0,amount=40,objectID=182858,text="1/1"}},worldTaskTitle="Automa Ops",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65142] = {id=65142,name="Portal Play",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="To aid in my studies, I have used a network of travel portals to install monitoring devices all over Zereth Mortis . My devices have been quite successful at collecting large amounts of research data. It's time now to collect the data they have obtained. Use my portal network to locate my Prying Eyes and collect any data they have gathered. I'll give you a portal initiator as well, allowing you to re-enter the portal network, incase you find yourself lost!",objectivesText="12 Prying Eye's research data collected. Progress: Have you collected all the data?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Portal Play"},
[65143] = {id=65143,name="Antros",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,starts={{x=0.48,y=0.05,mapID=1970}},ends={{x=0.48,y=0.05,mapID=1970}},coords={mapID=1970,x=0.48,y=0.05},questType="world",worldTaskTitle="Antros",db2QuestInfoID=112,db2QuestInfoName="Epic Elite World Quest"},
[65152] = {id=65152,name="A Hardened Bond",level=60,requiredLevel=60,faction="none",expansion=8,mapID=1698,questType="world",worldTaskTitle="A Hardened Bond"},
[65177] = {id=65177,name="Fruit of the Bloom",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We never know when something new may emerge from the confluence of creation and energy. The Catalyst Gardens have blossomed with a new crop of fruit. Their seeds may have special properties, and we wish to understand them. Please gather what you can find, and make the gardens safer for the future.",objectivesText="Gather Catamelon Seeds and slay Overgrowth in the Catalyst Gardens. Progress: How can one understand what cannot be defined?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Fruit of the Bloom"},
[65226] = {id=65226,name="Fleet-Footed and Fastidious",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="When the Mawsworn came to Zereth Mortis , they brought mawrats with them! A swarm of their mawrats overran my cave, making off with many of our research items! Rana is assembling a team to help recover the items. Meet up with her and aid in the effort.",objectivesText="Help Rana recover 6 Stolen Relics and slay 80 Thieving Mawrats . Progress: Have you dealt with those mawrats?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Fleet-Footed and Fastidious"},
[65230] = {id=65230,name="Bot-any",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,objectivesText="Vine-Choked or Overgrown creatures slain",starts={{x=0.474,y=0.803,mapID=1970}},ends={{x=0.474,y=0.803,mapID=1970}},coords={mapID=1970,x=0.474,y=0.803},questType="world",db2Objectives={{orderIndex=0,type=0,amount=12,objectID=183537,text="Vine-Choked or Overgrown creatures slain"}},worldTaskTitle="Bot-any",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
