[65234] = {id=65234,name="Sweet On Them",level=60,requiredLevel=60,faction="none",expansion=8,zoneID=13536,mapID=1970,starts={{x=0.63,y=0.58,mapID=1970}},ends={{x=0.63,y=0.58,mapID=1970}},coords={mapID=1970,x=0.63,y=0.58},questType="world",worldTaskTitle="Sweet On Them",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65244] = {id=65244,name="Devourable",expansion=8,mapID=1970,questType="world",db2Objectives={{orderIndex=0,type=0,amount=15,objectID=183765,text="Devourers slain"}},worldTaskTitle="Devourable",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65249] = {id=65249,name="The Jailer's Defeat",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="At long last, we have thwarted the Jailer's schemes. Both the Forge of Afterlives and Azeroth's world-soul have been restored, and the Shadowlands can now begin to recover from the anima drought. I know it is in your nature to push ever forward. But this was a monumental victory, and it deserves a moment of reflection.",objectivesText="Speak to Bolvar to relive the victory against the Jailer. Progress: Have you witnessed the defeat of the Jailer?",starts={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="The Jailer's Defeat"},
[65252] = {id=65252,name="Stomp It Now",expansion=8,mapID=1970,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=183790,text="Fissures closed"}},worldTaskTitle="Stomp It Now",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65255] = {id=65255,name="Forcing the Cycle",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The forces of Zovaal have been spreading their malign influence into the natural life within Provis Fauna. With the rate of their corruption, attempting to cleanse them one by one would be ill advised. Instead, we can just return their energies into the systems of Zereth Mortis to be used to create new fauna. Use this orb, let it absorb their energy as they die, and then cleanse it once it has been charged.",objectivesText="Charge and cleanse the Progenitor orb. Progress: Have you finished?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Forcing the Cycle"},
[65256] = {id=65256,name="Cluck, Cluck, Boom",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The endemic poultrids of Zereth Mortis have been influenced in an unseemly way by all these invaders. Use this device on the ones that have malfunctioned. Otherwise, they will do too much damage to the land.",objectivesText="Use the Kinematic Micro-Life Recalibrator to \"recalibrate\" Malfunctioned Poultrids in the Great Veldt. Progress: These mysterious ways must be understood.",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Cluck, Cluck, Boom"},
[65262] = {id=65262,name="Save the Vombata",expansion=8,mapID=1970,questType="world",db2Objectives={{orderIndex=0,type=0,amount=8,objectID=183838,text="Vombata Cubs saved"}},worldTaskTitle="Save the Vombata",db2QuestInfoID=109,db2QuestInfoName="World Quest"},
[65264] = {id=65264,name="Operation: Relocation",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Devourers have disrupted the avians nesting at Provis Esper. This may be our last chance to examine them before they become tainted, like the others. Capture several of the avians at Provis Esper and return them to Pilgrim Arizh for relocation and study. Deal with any problems that get in your way.",objectivesText="Deliver 8 wrangled Wild Proto Avians and slay 6 Soul-Parched Gorgers and 2 Reality Breachers in Provis Esper.",starts={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},ends={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Operation: Relocation"},
[65265] = {id=65265,name="Buried Remnants",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Much has been lost to the invading forces, those that came with destruction in their hearts. We cannot preserve this land as the First Ones intended if the Mawsworn are allowed to pulverize all remnants of their knowledge. See what you can recover from the sands of Provis Strata.",objectivesText="Recover Strange Artifacts from Provis Strata. Progress: What was before, will be again.",starts={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},ends={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Buried Remnants"},
[65268] = {id=65268,name="Bzzzzt!",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The vespoids of the region use debris in the area to form the core of their nests. While this is normally something we'd allow them to naturally do, they've started taking some of the relics we were studying. I have a device that should hopefully allow for the removal of such relics from their hives without damaging the core structure. Use it to retrieve these relics.",objectivesText="Use the enlightened broker device to remove the progenitor debris from vespoid nests .",starts={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},ends={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Bzzzzt!"},
[65269] = {id=65269,name="Obvious Plant",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The situation in the Catalyst Gardens is troubling. But most troubling of all is that we do not know more. If we had an understanding of the changing levels of energy emitted by the Creation Catalyst, we could make better decisions as to how to proceed. Take these sensors. Place them below the catalyst at the locations marked upon your map.",objectivesText="Place the Progenitor Magic Sensors in the Catalyst Gardens. Progress: Were you able to place the sensors?",starts={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},ends={{npcID=181179,x=0.612,y=0.514,zoneID=13536}},coords={x=0.612,y=0.514,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Obvious Plant"},
[65325] = {id=65325,name="Motes of Knowledge",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13928,mapID=1970,description="The creatures of Untamed Verdure are ingesting everything in sight. They have consumed our Compilation Nodule , and the Composition Motes needed for compilation. We Jiro require these resources. This area is too hazardous for unprotected Jiro operation. Please help us reclaim our resources. Mai Obet will assist you.",objectivesText="1 Compilation Nodule and 10 Composition Motes recovered. Progress: Have you recovered our resources?",starts={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Motes of Knowledge"},
[65326] = {id=65326,name="Circle of Strife",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Automa need assistance to operate properly. We fulfill this purpose, but outsiders have caused too many interruptions. We cannot properly address them all. Please assist Mai Obet in inspecting and reviewing the performance of the automa.",objectivesText="Inspect 10 Automa Constructors in Provis Flora. Progress: Do the automa meet expectations?",starts={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Circle of Strife"},
[65362] = {id=65362,name="Not of the Body",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Enemies of Zereth Mortis wear the guise of productive automa. They do not complete any desired tasks. Scan the automa to reveal enemy threats, then eliminate them. Mai Obet shall assist.",objectivesText="6 Dreadlord Infiltrators slain",starts={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=180289,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Not of the Body"},
[65363] = {id=65363,name="Dangerous State",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="Enemies have attacked the jiro and severed them from the circle. The jiro are no longer stable. They are a danger to the order of things. They must be removed.",objectivesText="Leashkeeper Helzid and 12 Dominated Jiro slain Progress: Have you removed the threat?",starts={{npcID=184434,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=184434,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Dangerous State"},
[65364] = {id=65364,name="Super Jiro",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The outsiders have disrupted the tasks and purpose of the jiro. We cannot allow this to continue. We will empower a larger jiro to help combat these threats. Jiro Prime will destroy the enemies that threaten Zereth Mortis . Help direct Jiro Prime to resolve our crisis.",objectivesText="Direct Jiro Prime to rescue 7 Distressed Jiro , while slaying 5 Mawbroken Automa and 100 Mawsworn forces . Progress: Have the threats been eliminated?",starts={{npcID=184434,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=184434,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Super Jiro"},
