[65445] = {id=65445,name="Necessary Resourcing",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13952,mapID=1970,description="Devourers are consuming neomotes. We need neomotes for necessary creation work. Without them, we are unable to complete our work. Eliminate the devourers and retrieve the neomotes.",objectivesText="Obtain 30 Neomote Residue and 3 Solidified Neomotes from Devourers in Zereth Mortis . Progress: Have you collected the neomotes?",starts={{npcID=184434,x=0.584,y=0.498,zoneID=13536}},ends={{npcID=184434,x=0.584,y=0.498,zoneID=13536}},coords={x=0.584,y=0.498,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Necessary Resourcing"},
[65735] = {id=65735,name="WANTED: Custos",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="A once-stable automa is showing signs of unusual dysfunction, attacking Enlightened along the road outside of Pilgrim's Grace. It is essential that the roads remain safe for our pilgrims. Rafiq has designated the elimination of this threat to be of the highest priority.",objectivesText="Eliminate Custos .",starts={{npcID=375972,x=0.354,y=0.655,zoneID=13536}},ends={{npcID=185587,x=0.604,y=0.51,zoneID=13536}},coords={x=0.354,y=0.655,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="WANTED: Custos",db2QuestInfoID=1,db2QuestInfoName="Group"},
[65748] = {id=65748,name="You Supply the Effort",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="The gear I provide is made available by the blessings of the First Ones and the... efforts of many other travelers. Each of us needs to provide for those that will follow later. Collect what provisions you come across in your exploration of Zereth Mortis . Keep a sharp eye out--they may be hidden in mysterious places. Return them here to me. I will in turn provide them to future travelers.",objectivesText="Locate 10 Enlightened Provisions from chests, nests, relics and other containers about Zereth Mortis . Progress: What have you found for me?",starts={{npcID=185713,x=0.35,y=0.656,zoneID=13536}},ends={{npcID=185713,x=0.35,y=0.656,zoneID=13536}},coords={x=0.35,y=0.656,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="You Supply the Effort"},
[65749] = {id=65749,name="The Necessity Of Equipment",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="I have been sharing research for some time with an associate of mine, Rafiq . It is only through our shared efforts that he has been able to acquire useful items. Deliver my latest research notes to Rafiq and see if you can earn favor with him. In time, he should be able to aid you with better equipment.",objectivesText="Collect Firim's Research Notes and deliver them to Rafiq . Progress: What is this you have brought me?",starts={{npcID=177958,x=0.342,y=0.486,zoneID=13536}},ends={{npcID=185587,x=0.604,y=0.51,zoneID=13536}},coords={x=0.342,y=0.486,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="The Necessity Of Equipment"},
[66042] = {id=66042,name="Patterns Within Patterns",level=60,requiredLevel=60,faction="both",expansion=8,zoneID=13536,mapID=1970,description="We stand at the origin of the Shadowlands. We must not allow this place to become its undoing. Work with our new allies, . Their assistance will be the difference between our success and the unmaking of all things.",objectivesText="Assist your allies in Zereth Mortis by completing World Quests, Daily Quests, looting treasures, and slaying rare creatures. Progress: In this place, all fates are intertwined.",starts={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},ends={{npcID=181183,x=0.35,y=0.648,zoneID=13536}},coords={x=0.35,y=0.648,source="quest_giver",zoneID=13536},questType="world",worldTaskTitle="Patterns Within Patterns"},
